/* Types */
/**
 *  Stage 16 (decision 0036): the accent colour family of the UI, in light and dark. Every one
 *  passes WCAG AA (`app/tests/contrast.test.ts`). The default is "orange", the logo's colour
 *  (decision 0038). A value this version does not know (from a newer device) reads as the
 *  default.
 */
export type AccentTheme = "teal" | "blue" | "violet" | "rose" | "orange" | "green";

/**  A configured account as the UI sees it. */
export type Account = {
	id: AccountId,
	email: string,
	displayName: string,
	color: AccountColor,
	imap: ServerSettings,
	smtp: ServerSettings,
	/**
	 *  Stage 14 (decision 0042): the provider this account signs in with instead of a
	 *  password (Microsoft, Google); `null` for a password.
	 */
	oauth: OAuthProvider | null,
	/**
	 *  Stage 14: `apiToken` for a JMAP account that signs in with an API token; left out for a
	 *  password (and for accounts that sign in with a provider).
	 */
	credential?: CredentialKind,
	/**
	 *  `false` for every new account. Only the user turns it on (stage 4); until then the
	 *  adapter opens mailboxes read-only and refuses every writing command.
	 */
	writesEnabled: boolean,
	status: AccountStatus,
	/**  Stage 14 (decision 0041): IMAP/SMTP or JMAP; left out for IMAP. */
	protocol?: Protocol,
};

/**  Index 0–7 into the eight account color tokens (`docs/DESIGN.md`). */
export type AccountColor = number;

/**  A user-defined group of accounts ("Arbeit", "Privat"). */
export type AccountGroup = {
	id: AccountGroupId,
	name: string,
	/**  Members in account order (oldest account first). */
	accountIds: AccountId[],
	/**  Order in the sidebar, ascending. */
	position: number,
};

/**  Stable id of an account group (UUID v4, lowercase hyphenated); synced like accounts. */
export type AccountGroupId = string;

/**
 *  Stable account id (UUID v4, lowercase hyphenated on the wire). It is the same on every
 *  device, so synced records refer to accounts by it, never by a local row id.
 */
export type AccountId = string;

/**  Sending settings of one account. */
export type AccountSendSettings = {
	accountId: AccountId,
	sentCopy: SentCopyMode,
	/**  What `sentCopy: auto` amounts to for this account: the server files sent mail itself. */
	serverSavesSent: boolean,
	/**
	 *  Stage 14 (decision 0034): the account is Gmail (IMAP host, or `X-GM-EXT-1` at the last
	 *  login), which files sent mail itself; the account settings say so.
	 */
	gmail: boolean,
};

/**
 *  What the user enters to set up an account (input of `testConnection` and `addAccount`).
 *  The password is a separate command argument.
 */
export type AccountSettings = {
	email: string,
	/**  Sender name; may be empty. */
	displayName: string,
	imap: ServerSettings,
	/**  Stored for stage 5 (sending). Stage 2 checks it for plausibility only. */
	smtp: ServerSettings,
	/**
	 *  Stage 14 (decision 0041): IMAP and SMTP unless the user chose JMAP in the advanced
	 *  options. With JMAP, `imap` names the JMAP server and `smtp` is replaced by a copy of it.
	 */
	protocol?: Protocol,
	/**
	 *  Stage 14: what the secret argument is. An API token only for JMAP; left out for a
	 *  password.
	 */
	credential?: CredentialKind,
};

/**  Coarse sync state of an account, for the status indicator. */
export type AccountState = 
/**  First connection attempt after start or after the user asked to retry. */
"connecting" | 
/**  A sync pass is running; `progress` is set during the first sync of a mailbox. */
"syncing" | 
/**  Connected and up to date; waiting for changes (IDLE or poll interval). */
"idle" | 
/**  Not connected; retrying with backoff. `error` says why, `retryAt` when. */
"offline" | 
/**  Stopped until the user acts (wrong password, untrusted certificate, unsupported server). */
"error";

/**
 *  Sync status of one account. Invariants by `state`:
 *  `syncing` may carry `progress`; `offline` carries `error` (null only before the first
 *  failure) and `retryAt` (null while a reconnect is running); `error` always carries `error`.
 */
export type AccountStatus = {
	state: AccountState,
	progress: SyncProgress | null,
	error: IpcError | null,
	/**  Unix milliseconds of the next reconnect attempt. */
	retryAt: number | null,
	/**  Unix milliseconds when the last complete sync pass finished, in any state. */
	lastSyncAt: number | null,
};

/**  What an operation was recorded for, for the activity view. */
export type ActionKind = "mark_read" | "mark_unread" | "flag" | "unflag" | "add_keyword" | "remove_keyword" | "archive" | "delete" | "delete_permanently" | "move" | "spam" | "not_spam" | "create_mailbox" | 
/**  Counter-operations of an undone batch. */
"undo" | 
/**
 *  Stage 5: sending a message, and what follows its acceptance (the copy in Sent, the
 *  draft's copy removed, `\Answered` on the original).
 */
"send" | 
/**  Stage 5: a new version of a draft in the Drafts folder (the old one removed). */
"save_draft" | 
/**  Stage 5: the server copy of a discarded draft removed. */
"delete_draft" | 
/**  Stage 14: a Gmail label added or removed (decision 0034). */
"add_label" | "remove_label" | 
/**
 *  Stage 16: a message copied to another account (decision 0033). A move between
 *  accounts is recorded as `move`.
 */
"copy" | 
/**  Audit 24.11.2026: a folder of the user's own renamed or deleted. */
"rename_mailbox" | "delete_mailbox";

/**  Result of applying an action. */
export type ActionResult = {
	/**  For undo; null if nothing was recorded (no-op, or every change cancelled a queued one). */
	batch: BatchId | null,
	/**  Operations recorded. */
	queued: number,
	/**
	 *  Queued operations that this action cancelled out (for example "read" after a still
	 *  queued "unread").
	 */
	cancelled: number,
};

/**  A mailbox address. `email` may be empty for broken headers; groups are flattened. */
export type Address = {
	/**  Decoded display name (RFC 2047), null if none. */
	name: string | null,
	email: string,
};

/**  Whether cloud providers may see an account's mail. Every account starts without. */
export type AiAccountCloud = {
	accountId: AccountId,
	cloudAllowed: boolean,
};

/**  The answer to a question in natural language. */
export type AiAnswer = {
	/**
	 *  `false`: honestly nothing found (no candidates, or nothing in them answers it);
	 *  `statements` is empty then.
	 */
	found: boolean,
	statements: AiClaim[],
	/**  The search the question became (stage 7 language; the UI can offer it). */
	query: string,
	/**  Messages the search found. */
	candidates: number,
	/**  Candidates not sent because their account has no cloud permission. */
	excluded: number,
	/**  Statements dropped for lack of a valid reference. */
	dropped: number,
	/**  One per request sent. */
	transfers: AiTransfer[],
	/**  See [`AiSummary::link_token`]. */
	linkToken: RenderToken | null,
};

/**
 *  Which functions are usable right now (for showing the AI panel and buttons): AI is on and
 *  the function has a profile with a model.
 */
export type AiAvailability = {
	enabled: boolean,
	summary: boolean,
	replySuggestion: boolean,
	writingHelp: boolean,
	search: boolean,
};

/**  A statement with the messages it is based on (each one exists and was sent). */
export type AiClaim = {
	text: string,
	/**
	 *  `text` for display (decision 0028): links the core found are `link` segments, opened
	 *  only through `describeLink`/`openLink` with the result's `linkToken`.
	 */
	segments: TextSegment[],
	sources: MessageId[],
};

/**  Result of "test connection" (no mail content is sent). */
export type AiConnectionTest = {
	/**  Models the provider lists. */
	models: number,
	/**  The profile's model is among them (`null`: no model chosen). */
	modelListed: boolean | null,
	/**  A short test request with the profile's model answered (`null`: no model chosen). */
	chatOk: boolean | null,
	/**  Why the test request failed. */
	chatError: ErrorCode | null,
};

export type AiDeadline = {
	text: string,
	/**  `text` for display, as in [`AiClaim::segments`]. */
	segments: TextSegment[],
	/**  As the message states it ("Friday", "30.11."). */
	due: string,
	sources: MessageId[],
};

/**
 *  The functions that can use a provider. The open-reply hints are not one of them: they work
 *  without AI (decision 0024).
 */
export type AiFunction = "summary" | "reply_suggestion" | "writing_help" | "search";

/**  Which profile a function uses; `null` is off. */
export type AiFunctionChoice = {
	function: AiFunction,
	profileId: string | null,
};

/**
 *  How a profile's key changes when it is saved. Only ever sent from the UI to the core; the
 *  core wraps the key in a [`crate::Secret`] at once. `Debug` never shows it.
 */
export type AiKeyChange = 
/**
 *  Keep the stored key (or none). When the base URL's server (scheme, host or port)
 *  changes, the stored key is removed instead.
 */
{ type: "keep" } | 
/**  Delete the stored key. */
{ type: "remove" } | 
/**  Store this key in the keychain (an empty key is `remove`). */
{ type: "set"; key: string };

/**
 *  Where a profile's base URL points. `thisDevice` and `localNetwork` are shown as "local":
 *  the transport only ever connects to such addresses for them.
 */
export type AiLocality = "this_device" | "local_network" | 
/**  A cloud provider: consent first, and only accounts with cloud permission. */
"internet";

/**  A model of a provider. */
export type AiModel = {
	id: string,
	displayName: string | null,
};

/**  Stage 13 (decision 0028): whether the AI panel of the main window is unfolded or folded in. */
export type AiPanelState = "open" | "folded";

/**  A known endpoint for "new profile". */
export type AiPreset = {
	name: string,
	kind: AiProviderKind,
	baseUrl: string,
	needsKey: boolean,
	locality: AiLocality,
};

/**  A provider profile as the settings show it. The key is in the system keychain. */
export type AiProfileInfo = {
	/**  32 lowercase hex digits. */
	id: string,
	name: string,
	kind: AiProviderKind,
	baseUrl: string,
	/**  Empty until the user picks one. */
	model: string,
	/**  Ask for the JSON schema of the answer; off for servers or models that reject it. */
	structuredOutput: boolean,
	maxOutputTokens: number | null,
	/**  A key is stored in the keychain (never shown). */
	hasKey: boolean,
	/**
	 *  The last save changed the base URL's server (scheme, host or port) without a new key,
	 *  so the core removed the stored key (a key belongs to the server it was entered for).
	 *  The settings ask for it again; cleared by the next save of the profile.
	 */
	keyRemovedOnServerChange: boolean,
	/**  Host and port of the base URL ("an wen"). */
	host: string,
	locality: AiLocality,
	/**
	 *  When the user agreed to send data to this provider (Unix ms). Always `null` for local
	 *  profiles, which need no consent. Changing the base URL's host withdraws it.
	 */
	consentAt: number | null,
	/**  A cloud profile without consent: the first request fails with `ai_consent_required`. */
	needsConsent: boolean,
};

/**  A profile to create (`id` null) or change. */
export type AiProfileInput = {
	id: string | null,
	name: string,
	kind: AiProviderKind,
	baseUrl: string,
	model: string,
	structuredOutput: boolean,
	maxOutputTokens: number | null,
	key: AiKeyChange,
};

/**  Wire protocol of a profile (decision 0019). */
export type AiProviderKind = 
/**
 *  `POST {base}/chat/completions`: Ollama, LM Studio, llama.cpp server, OpenRouter,
 *  OpenAI. The base URL includes `/v1`.
 */
"openai_compatible" | 
/**  Anthropic Messages API (`POST {base}/v1/messages`). */
"anthropic";

/**  A reply suggestion; "open draft" (`aiOpenReplyDraft`) turns it into an editable draft. */
export type AiReplySuggestion = {
	text: string,
	/**  `text` with its links as segments (decision 0028). */
	segments: TextSegment[],
	/**  The message the reply answers. */
	inReplyTo: MessageId,
	transfer: AiTransfer,
	/**  See [`AiSummary::link_token`]. */
	linkToken: RenderToken | null,
};

/**  One entry of the request log: metadata only, never content or keys. */
export type AiRequestEntry = {
	id: AiRequestId,
	/**  Unix ms. */
	at: number,
	function: AiFunction,
	profileName: string,
	host: string,
	locality: AiLocality,
	model: string,
	mails: number,
	bytes: number,
	outcome: AiRequestOutcome,
	/**  For `failed`: the error code. */
	error: ErrorCode | null,
	durationMs: number,
};

/**  Id of a request log entry; grows with every entry. The cursor of `listAiRequests`. */
export type AiRequestId = number;

/**  How a request ended. */
export type AiRequestOutcome = "ok" | "cancelled" | "failed";

/**  A page of the request log, newest first. */
export type AiRequestPage = {
	entries: AiRequestEntry[],
	/**  Pass as `before` for the next page; `null` at the end. */
	nextBefore: AiRequestId | null,
};

/**  Progress of a running request, as `aiRequest` events. */
export type AiRequestPhase = 
/**  About to send this (one per provider request; a question has up to two). */
{ phase: "sending"; transfer: AiTransfer } | 
/**  Characters of the answer received so far. */
{ phase: "receiving"; chars: number } | 
/**  Done (the command returns the result or the error). */
{ phase: "finished"; outcome: AiRequestOutcome };

/**  The settings page "AI in the app". */
export type AiSettingsInfo = {
	/**  Master switch; off until the user turns it on. Off: no request leaves the device. */
	enabled: boolean,
	profiles: AiProfileInfo[],
	/**  One entry per [`AiFunction`], in that order. */
	functions: AiFunctionChoice[],
	/**  One entry per account. */
	accounts: AiAccountCloud[],
	presets: AiPreset[],
	openReplies: OpenReplySettings,
};

/**  A thread summary. */
export type AiSummary = {
	keyPoints: AiClaim[],
	openQuestions: AiClaim[],
	deadlines: AiDeadline[],
	/**  Statements dropped because they named no message that was sent. */
	dropped: number,
	transfer: AiTransfer,
	/**
	 *  The token of the links in the segments of this result (decision 0028); `null` when the
	 *  result has none.
	 */
	linkToken: RenderToken | null,
};

/**  Target languages of "translate". */
export type AiTargetLanguage = "en" | "de" | "fr" | "es" | "it" | "nl" | "pt" | "pl";

export type AiTone = "formal" | "friendly" | "neutral" | "direct";

/**  What one request sends and to whom, shown before and while it runs. */
export type AiTransfer = {
	function: AiFunction,
	profileId: string,
	profileName: string,
	/**  The recipient: host and port of the provider. */
	host: string,
	locality: AiLocality,
	model: string,
	/**  Messages sent (0 for a question's first step and for the writing help). */
	mails: number,
	/**  Accounts the messages belong to. */
	accounts: AccountId[],
	/**  Bytes of text sent. */
	bytes: number,
	/**  Attachment names sent (never contents). */
	attachmentNames: number,
	/**  Quoted passages left out because an earlier message has them. */
	quotesRemoved: number,
	trimming: AiTrimming,
};

/**
 *  What `aiPrepareTransfer` prepares without sending (decision 0028): a function with the
 *  input it would get. The tag is the function's name.
 */
export type AiTransferInput = { function: "summary"; messageId: MessageId } | { function: "reply_suggestion"; messageId: MessageId } | { function: "writing_help"; passage: string; task: AiWritingTask } | 
/**
 *  The first request of a question (the question alone). The candidates follow in a second
 *  request whose size is known only after the local search; `aiRequest` announces it.
 */
{ function: "search"; question: string };

/**  What was shortened for the length budget. All zero: nothing. */
export type AiTrimming = {
	mailsLeftOut: number,
	mailsShortened: number,
	charsRemoved: number,
};

/**
 *  The rewritten passage, for the preview. Nothing in the draft changes until the UI applies
 *  it.
 */
export type AiWritingResult = {
	text: string,
	/**  `text` with its links as segments (decision 0028). */
	segments: TextSegment[],
	transfer: AiTransfer,
	/**  See [`AiSummary::link_token`]. */
	linkToken: RenderToken | null,
};

/**  What the writing help does with the passage. */
export type AiWritingTask = { type: "improve" } | { type: "shorten" } | { type: "rephrase" } | { type: "tone"; tone: AiTone } | { type: "translate"; language: AiTargetLanguage };

/**  Version information shown under Settings, About. */
export type AppInfo = {
	version: string,
	/**  Short git hash at build time, null if unknown. */
	commit: string | null,
	/**  RFC 3339 build timestamp, null if unknown. */
	buildDate: string | null,
	platform: Platform,
};

/**  Stage 16 (decision 0033): what "send and archive" did with the original. */
export type ArchiveAfterSend = 
/**  The message is not accepted yet; nothing is archived if it fails or is cancelled. */
"waiting" | 
/**
 *  Accepted: the original's move to the archive is queued in the outbox (or it lay there
 *  already, or is no longer stored locally).
 */
"queued" | 
/**
 *  Accepted, but the account has no archive mailbox: the original stayed where it was.
 *  The UI can offer to choose one (`setMailboxRole`).
 */
"no_archive_mailbox";

/**  One attachment in the reading pane. */
export type AttachmentInfo = {
	/**  Position for `saveAttachment`/`openAttachment`; stable for the message. */
	index: number,
	/**
	 *  Sanitized file name (no path separators, reserved names, control or bidi characters);
	 *  never empty.
	 */
	name: string,
	/**  Lower-case MIME type as declared. */
	mimeType: string,
	/**  Decoded size in bytes; estimated from the encoded size while `local` is false. */
	size: number,
	/**  Opening it can run code (by extension or type); `openAttachment` asks for confirmation. */
	executable: boolean,
	/**  The content is stored locally (false for attachments of a partial message). */
	local: boolean,
	/**  Stage 16 (decision 0036): what `previewAttachment` shows; null when it has no preview. */
	preview: PreviewKind | null,
};

/**
 *  `previewAttachment`: what the preview pane shows. Images are `data:` URIs of bytes the core
 *  encoded itself; text is shown as text, never as markup.
 */
export type AttachmentPreview = { kind: "image"; 
/**  `data:image/png;base64,…` or `data:image/jpeg;base64,…`, encoded by the core. */
dataUrl: string; width: number; height: number; 
/**  The image was scaled down to fit [`MAX_PREVIEW_EDGE`]. */
scaled: boolean } | { kind: "pdf"; 
/**  `data:image/png;base64,…` of the page, rasterised by the core. */
dataUrl: string; width: number; height: number; 
/**  0-based page shown. */
page: number; 
/**  Pages the preview can show (at most [`MAX_PREVIEW_PDF_PAGES`]). */
pages: number; 
/**  The document has more pages than the preview shows. */
morePages: boolean } | { kind: "text"; text: string; 
/**  Cut after [`MAX_PREVIEW_TEXT_BYTES`]. */
truncated: boolean };

/**  `ROLE` of an attendee. */
export type AttendeeRole = "chair" | 
/**  `REQ-PARTICIPANT`. */
"required" | 
/**  `OPT-PARTICIPANT`. */
"optional" | 
/**  `NON-PARTICIPANT` (for information only). */
"non_participant";

/**  A newer version announced by the update manifest. */
export type AvailableUpdate = {
	version: string,
	/**  Release notes as plain text (the UI never renders them as HTML or Markdown). */
	notes: string | null,
	/**  Publication date, RFC 3339, if the manifest has one. */
	pubDate: string | null,
};

/**  What the Dock (macOS) or taskbar (Windows) icon counts. */
export type BadgeMode = "off" | 
/**  Unread messages in the inboxes of the visible accounts. */
"inboxUnread" | 
/**  Unread messages of people (and unclassified ones) in those inboxes. */
"peopleUnread";

/**  The operations of one action (one call, possibly many messages). Undo works on a batch. */
export type BatchId = number;

/**  A sender whose new mail goes to the junk folder (or is hidden on read-only accounts). */
export type BlockedSender = {
	/**  Normalised address (lower case, IDNA domain). */
	address: string,
	/**  Unix milliseconds. */
	createdAt: number,
};

/**  Which rendering of the body the UI asks `getMessage` for. */
export type BodyFormat = 
/**  HTML if the message has an HTML part, otherwise text. */
"auto" | "html" | "text";

export type BodyUnavailableReason = 
/**  The account is not connected and the body was never stored. */
"offline" | 
/**  The message no longer exists on the server (moved or deleted meanwhile). */
"notOnServer" | 
/**  The fetch failed; see `error`. */
"fetchFailed";

/**  One bundle: a category within a date section. */
export type BundleKey = {
	category: MessageCategory,
	section: number,
};

/**  Counter and chips of a bundle, over every member seen so far. */
export type BundleSummary = {
	key: BundleKey,
	count: number,
	unread: number,
	/**  Most frequent senders first; equal counts: the one with the newer message first. */
	senders: SenderChip[],
};

/**  One `VEVENT`. */
export type CalendarEvent = {
	uid: string | null,
	/**  The title; one line. */
	summary: string | null,
	/**  One line, as written (a room, an address or a meeting link). */
	location: string | null,
	/**
	 *  Plain text with `\n` line breaks, cut to a few KiB (then ending in `…`). Untrusted like
	 *  any mail text: links in it are opened only through the link check.
	 */
	description: string | null,
	organizer: CalendarPerson | null,
	/**  The first attendees in file order (capped, see `mail_content::MAX_CALENDAR_ATTENDEES`). */
	attendees: CalendarPerson[],
	/**  Every `ATTENDEE` of the event, also those beyond `attendees`. */
	attendeeCount: number,
	/**  `None` when the event has no readable `DTSTART` (allowed in `CANCEL` and `REPLY`). */
	start: CalendarTime | null,
	/**
	 *  Exclusive end, from `DTEND` or `DTSTART` + `DURATION`. An all-day event without either
	 *  lasts one day; a timed one without either has no end (`None`).
	 */
	end: CalendarTime | null,
	recurrence: CalendarRecurrence | null,
	/**
	 *  Set when this event changes or cancels one occurrence of a recurring event
	 *  (`RECURRENCE-ID`): the original start of that occurrence.
	 */
	recurrenceId: CalendarTime | null,
	status: EventStatus | null,
	/**  `SEQUENCE`: revision of the invitation, 0 for the first one. */
	sequence: number,
	/**  The organizer cancelled it: `METHOD:CANCEL` or `STATUS:CANCELLED`. */
	cancelled: boolean,
};

/**
 *  A calendar file as far as it could be read. Never an error: an unreadable file has no events
 *  and says why in `problems`.
 */
export type CalendarInvite = {
	/**
	 *  `METHOD` of the iTIP message (RFC 5546) in upper case: `REQUEST` (invitation or update),
	 *  `CANCEL`, `REPLY`, `PUBLISH`, `COUNTER`, … `None` for a plain calendar file.
	 */
	method: string | null,
	/**
	 *  The events in file order (capped, see `mail_content::MAX_CALENDAR_EVENTS`). A recurring
	 *  meeting with changed occurrences has one master event and one event per changed
	 *  occurrence (with `recurrence_id`).
	 */
	events: CalendarEvent[],
	/**  What was damaged or left out; empty for a well-formed file. */
	problems: CalendarProblem[],
};

/**  One calendar part of a message, read for display. */
export type CalendarInviteInfo = {
	partId: number,
	invite: CalendarInvite,
};

/**  Organizer or attendee (`CAL-ADDRESS` with its parameters). */
export type CalendarPerson = {
	/**  `CN`, the display name. */
	name: string | null,
	/**  The address of a `mailto:` value (or of the `EMAIL` parameter). */
	email: string | null,
	/**  `ROLE`; attendees only. `None` when missing (RFC 5545 then means `required`) or unknown. */
	role: AttendeeRole | null,
	/**  `PARTSTAT`; attendees only. `None` when missing or unknown. */
	status: ParticipationStatus | null,
};

/**  Something about the calendar file that is damaged or was left out. */
export type CalendarProblem = {
	code: CalendarProblemCode,
	/**
	 *  What it is about, for diagnostics (not translated), cut to 64 bytes: the `TZID` for
	 *  `unknown_time_zone`, the value as written for `bad_date`/`bad_duration`/`bad_recurrence`,
	 *  the property name for `line_too_long`, `"2097152 bytes"` or `"100000 lines"` for
	 *  `too_large`, the number of events found for `too_many_events`. `None` when there is
	 *  nothing to add.
	 */
	detail: string | null,
};

/**  Problem codes of a calendar file. */
export type CalendarProblemCode = 
/**  Not a calendar: no `BEGIN:VCALENDAR` and no event. */
"not_calendar" | 
/**  A calendar without events (only tasks, free/busy data, time zones, or nothing). */
"no_event" | 
/**  Larger than the input limit (bytes or lines): only the beginning was read. */
"too_large" | 
/**  More events than the limit; the rest was skipped. `detail`: how many there were. */
"too_many_events" | 
/**  The file ends inside a component (`END` missing, cut off): what was read is shown. */
"truncated" | 
/**  `BEGIN`/`END` do not match, components nested too deep, or an event outside a calendar. */
"broken_structure" | 
/**  A content line that cannot be read (no colon, invalid name, unclosed quote); skipped. */
"broken_line" | 
/**  A property line longer than the line limit; its value was cut. */
"line_too_long" | 
/**  Bytes that are not UTF-8 were replaced by U+FFFD. */
"malformed_text" | 
/**
 *  A date or date-time that cannot be read (`DTSTART`, `DTEND`, `RECURRENCE-ID`, `UNTIL`),
 *  or `DTSTART` and `DTEND` of different kinds; the value is left out.
 */
"bad_date" | 
/**  `DURATION` cannot be read or is negative; the end is left out. */
"bad_duration" | 
/**  `RRULE` without a readable `FREQ`; the recurrence is left out. */
"bad_recurrence" | 
/**  `DTEND` is before `DTSTART`; the end is left out. */
"end_before_start" | 
/**  An event without `DTSTART` (outside `CANCEL`, `REPLY` and other replies). */
"missing_start" | 
/**
 *  A `TZID` that is neither known to the system, nor a Windows zone name, nor defined by a
 *  `VTIMEZONE` in the file: the time is shown as floating (in the user's zone).
 */
"unknown_time_zone" | 
/**  The reader failed unexpectedly (a bug); nothing is shown. */
"internal";

/**  `RRULE`, described for the card ("every 2 weeks on Monday until 31 December"), not expanded. */
export type CalendarRecurrence = {
	frequency: RecurrenceFrequency,
	/**  `INTERVAL`, at least 1: every `interval` days, weeks, months or years. */
	interval: number,
	/**  `COUNT`: number of occurrences. */
	count: number | null,
	/**  `UNTIL`: last possible occurrence (inclusive). */
	until: CalendarTime | null,
	/**  `BYDAY`, normalised: `MO`, `-1SU` (last Sunday), `2TU` (second Tuesday). */
	byDay: string[],
	/**  `BYMONTHDAY`: 1 to 31, or -1 (last day) to -31. */
	byMonthDay: number[],
	/**  `BYMONTH`: 1 to 12. */
	byMonth: number[],
	/**  `BYSETPOS`: which of the matching days (`-1` = the last). */
	bySetPos: number[],
	/**
	 *  The `RRULE` value as written (cut to 256 bytes), for what the fields above do not cover
	 *  (`BYWEEKNO`, `BYHOUR`, …).
	 */
	rule: string,
};

/**  A point in time of an event. */
export type CalendarTime = 
/**  A calendar day without time or zone (`VALUE=DATE`, all-day events): `YYYY-MM-DD`. */
{ kind: "date"; date: string } | 
/**  A date and time. */
{ kind: "dateTime"; 
/**  The instant in Unix milliseconds. Show it in the user's own time zone. */
utc: number; 
/**
 *  The wall-clock time as the file wrote it, `YYYY-MM-DDTHH:MM:SS` (in `zone`; UTC for
 *  `zone: "UTC"`). For an end computed from `DURATION` it is start + duration.
 */
local: string; 
/**
 *  The zone `local` is in: `"UTC"`, an IANA name (`America/New_York`; also when the
 *  file used a Windows name such as `Eastern Standard Time` or a prefixed name such as
 *  `/mozilla.org/…/Europe/Berlin`), or the `TZID` as written when only the file's own
 *  `VTIMEZONE` defines it. `None` when floating.
 */
zone: string | null; 
/**
 *  No usable zone: a floating time (no `TZID`, no `Z`) or an unknown `TZID`
 *  (`unknown_time_zone` problem). `utc` was computed in the user's own time zone, so the
 *  wall-clock time stays as written.
 */
floating: boolean };

/**
 *  Server capabilities the engine and the UI ask about. Nothing is faked: what a server lacks
 *  is hidden or explained (`docs/ARCHITECTURE.md`). Custom keywords are a per-mailbox property
 *  (`PERMANENTFLAGS \*`), see [`crate::SelectedMailbox::keywords_allowed`].
 */
export type Capabilities = {
	imap4rev1: boolean,
	/**  RFC 2177. Without it, new mail is found by polling. */
	idle: boolean,
	/**  RFC 7162. Without it, flag changes are found by re-reading flags window by window. */
	condstore: boolean,
	qresync: boolean,
	enable: boolean,
	/**  RFC 6851 (`MOVE`), stage 4. */
	move: boolean,
	/**  RFC 4315, stage 4 and 5. */
	uidplus: boolean,
	/**  RFC 6154, folder roles. */
	specialUse: boolean,
	/**  RFC 5819, all folder counters in one round trip. */
	listStatus: boolean,
	/**  RFC 7888, saves a round trip per APPEND. */
	literalPlus: boolean,
	/**  RFC 4731, compact `UID SEARCH` results. */
	esearch: boolean,
	/**
	 *  Stage 14 (decision 0034): `X-GM-EXT-1`, the Gmail extensions. Labels instead of
	 *  folders: `X-GM-MSGID` identifies one message across all its labels, `X-GM-LABELS`
	 *  lists and changes them; the server files sent mail itself.
	 */
	gmail: boolean,
	/**
	 *  Stage 14, block D (decision 0041): the server speaks JMAP, not IMAP. The adapter
	 *  numbers messages itself (`imap4rev1` is false); the other flags say what it emulates:
	 *  IDLE is push over EventSource (RFC 8620 section 7.3), CONDSTORE the server's state
	 *  strings, MOVE and UIDPLUS changes of `mailboxIds` with UIDs the adapter assigns. Left
	 *  out for IMAP servers.
	 */
	jmap?: boolean,
	/**
	 *  Every announced capability, upper case, sorted, without duplicates. On JMAP the
	 *  capability URIs of the session resource.
	 */
	names: string[],
};

/**  The category of a message, why, and whether it belongs to the "Priority" block. */
export type CategoryDecision = {
	category: MessageCategory,
	reason: CategoryReason,
	/**  The important mark that matched (sender, domain or list); `None` outside "Priority". */
	important: SenderKey | null,
};

/**
 *  Why a message got its category: the first rule that matched (decision 0016 lists the order).
 *  Values are copied from the message (header values cut to a few dozen characters).
 */
export type CategoryReason = 
/**  The user's correction ("always as …") for this sender, list or domain. */
{ kind: "userRule"; key: SenderKey } | 
/**  `Auto-Submitted` other than `no` (RFC 3834): written by a program. */
{ kind: "autoSubmitted"; value: string } | 
/**
 *  An automatic reply (vacation, out of office): `Precedence: auto_reply`, `X-Autoreply`,
 *  `X-Autorespond` or a subject such as "Automatic reply:" / "Automatische Antwort:".
 */
{ kind: "autoReply"; evidence: string } | 
/**
 *  A delivery, read or other report (`multipart/report`, `MAILER-DAEMON`, empty
 *  `Return-Path`).
 */
{ kind: "report"; evidence: string } | 
/**  A header only a known system writes (`X-GitHub-Reason`, `X-GitLab-Project`, ...). */
{ kind: "knownSystem"; system: string; header: string } | 
/**  Sent from one of the user's own addresses. */
{ kind: "ownMessage" } | 
/**  Answers a message the user sent. */
{ kind: "replyToOwn" } | 
/**  A mailing list the members write to (`List-Post`). */
{ kind: "discussionList"; listId: string | null } | 
/**  A mailing list (`List-Id`). */
{ kind: "mailingList"; listId: string } | 
/**  `Precedence: bulk`, `list` or `junk`. */
{ kind: "precedence"; value: string } | 
/**
 *  Newsletter software or a campaign header (`X-CSA-Complaints`, `X-Campaign`, the
 *  `X-Mailer` of a newsletter tool, a marketing service's bounce address).
 */
{ kind: "campaign"; evidence: string } | 
/**  The user has written to this sender before. */
{ kind: "correspondent"; sent: number } | 
/**  Offers unsubscribing (`List-Unsubscribe`) and nothing points to a person. */
{ kind: "unsubscribe" } | 
/**
 *  Sent through a mailing service (`Feedback-ID`, a service's bounce address) and offers no
 *  unsubscribing: a transactional mail.
 */
{ kind: "mailingService"; evidence: string } | 
/**  An address nobody reads (`noreply@`, `nicht-antworten@`). */
{ kind: "noReplyAddress"; address: string } | 
/**  An address of a program (`notifications@`, `alerts@`, `rechnung@`). */
{ kind: "automatedAddress"; address: string; pattern: string } | 
/**  An address that sends newsletters (`newsletter@`, `news@`). */
{ kind: "newsletterAddress"; address: string; pattern: string } | 
/**  Nothing points to a program or a list. */
{ kind: "noBulkSignals" } | 
/**  Stage 9: a local rule set the category of this message (its name at the time). */
{ kind: "localRule"; ruleName: string };

/**  Stage 10: pasted HTML as the composer gets it back (`cleanPastedHtml`). */
export type CleanedPaste = {
	/**
	 *  Editor HTML: the mail allowlist, no script, no style, no image, no external reference;
	 *  links only `http`, `https`, `mailto`.
	 */
	html: string,
	/**  Images that were dropped (web addresses, local files, `data:`, other mails' `cid:`). */
	imagesRemoved: number,
	/**  Colours, fonts, sizes, tables or headings were simplified. */
	formattingSimplified: boolean,
};

/**
 *  Stage 17: one view of the column's "Views" section (and of the rail), in the user's order,
 *  shown or hidden. Which views exist is the UI's business, like the commands of the shortcuts:
 *  the core checks the form of the id only.
 */
export type ColumnView = {
	/**  View id of the UI: 1 to 64 ASCII letters, digits, `_` or `-`. */
	id: string,
	shown: boolean,
};

/**  Rich text (HTML from the editor, sent as `multipart/alternative`) or plain text only. */
export type ComposeFormat = "html" | "text";

/**  An identity for the composer: the sender choice and its text signature. */
export type ComposeIdentity = {
	id: IdentityId,
	accountId: AccountId,
	email: string,
	name: string,
	replyTo: string | null,
	isDefault: boolean,
	/**
	 *  Plain text without the `-- ` separator (added when the message is put together): the
	 *  text of the default signature for new mails (stage 5 field, kept).
	 */
	signature: string | null,
	/**  Default signature of new mails (stage 10); null = none. */
	signatureNew: SignatureId | null,
	/**  Default signature of replies and forwards (stage 10); null = none. */
	signatureReply: SignatureId | null,
};

/**
 *  The fields a `mailto:` link fills in a new draft. Recipients are checked and unique across
 *  To, Cc and Bcc (the address as it goes into the message: local part as written, domain in
 *  ASCII); `subject` is one line; `body` is plain text with `\n` line breaks.
 */
export type ComposeRequest = {
	to: Address[],
	cc: Address[],
	bcc: Address[],
	subject: string | null,
	body: string | null,
	/**  Message-ID of the message this answers, without angle brackets. */
	inReplyTo: string | null,
	/**  What the user should know before sending; shown as hints in the composer. */
	notices: MailtoNotice[],
};

/**  App-wide compose settings. */
export type ComposeSettings = {
	/**  Undo delay before a message is submitted, 0 to [`MAX_SEND_DELAY_SECS`]. */
	sendDelaySeconds: number,
	/**
	 *  Stage 8 (decision 0025): where a new reply or forward puts the answer relative to the
	 *  quote: `above` (answer above, quote below; the default and the behaviour before), or
	 *  `below`. The composer can still change it per draft. Left out by an older caller: the
	 *  default.
	 */
	defaultQuotePosition?: QuotePosition,
	/**
	 *  Stage 16 (decision 0033): new replies (and replies to all) start with
	 *  [`Draft::archive_original`] on. Off by default; synced.
	 */
	archiveOnReply?: boolean,
	/**  Stage 16: how read-receipt requests of incoming mail are handled. Synced. */
	readReceipts?: ReadReceiptPolicy,
};

/**
 *  Why an operation ended in [`OperationState::Conflict`]. In every case the server state is
 *  kept and shown.
 */
export type ConflictReason = 
/**  The message is no longer in the mailbox: moved or deleted by another client. */
"gone" | 
/**
 *  The message was changed on the server after the app last saw it (CONDSTORE
 *  `UNCHANGEDSINCE`), and the server's state differs from what was asked.
 */
"modified" | 
/**  The mailbox was recreated on the server (new UIDVALIDITY); its old UIDs are void. */
"mailbox_reset" | 
/**  The mailbox no longer exists on the server. */
"mailbox_gone";

/**  A successful connection test. Failures arrive as `IpcError` with a specific code. */
export type ConnectionTestResult = {
	/**
	 *  What the IMAP server offers after login, for hints such as "no IDLE: new mail appears
	 *  with a delay".
	 */
	capabilities: Capabilities,
};

/**  One address of a contact and how it was used. */
export type ContactAddressInfo = {
	/**  The address to write to (local part as last written, Unicode domain). */
	email: string,
	/**  Messages the user sent to it. */
	sent: number,
	/**  Messages received from it (only from people, not newsletters or notifications). */
	received: number,
	/**  Last message to or from it, Unix ms. */
	lastUsed: number | null,
};

/**
 *  A possible duplicate. Nothing is merged unless the user confirms (`mergeContacts` with
 *  `confirmed: true`); `dismissDuplicate` hides it for good.
 */
export type ContactDuplicate = {
	reason: DuplicateReason,
	/**  The shared name (`sameName`). */
	name: string | null,
	/**  The names seen (`namesDiffer`). */
	names: string[],
	/**  Two contacts, or one for `namesDiffer`. */
	contacts: ContactEntry[],
};

/**  A contact of the directory. */
export type ContactEntry = {
	/**  Normalised address of the preferred address: the contact's id in every command. */
	key: string,
	/**  The name to show: the user's, else the most used one seen in mail. */
	name: string | null,
	/**  The name the user gave (synchronised between devices). */
	userName: string | null,
	/**  The preferred address to write to. */
	email: string,
	/**  Every address, the preferred one first. */
	addresses: ContactAddressInfo[],
	/**  Over all addresses. */
	sent: number,
	received: number,
	/**  Unix ms. */
	lastUsed: number | null,
};

/**  Merging contacts the user confirmed as one person. */
export type ContactMergeRequest = {
	/**  Any address of the contact that stays; its preferred address stays preferred. */
	keep: string,
	/**  Any address of each contact merged into it. */
	merge: string[],
	/**
	 *  Must be `true`: the user confirmed the merge. Without it nothing changes
	 *  (`confirmation_required`).
	 */
	confirmed: boolean,
};

/**
 *  One page of the directory, highest ranked first (frequency and recency in one score:
 *  sent mail counts four times a received one, and every 30 days a message counts half).
 */
export type ContactPage = {
	items: ContactEntry[],
	/**  Pass to `listContacts` for the next page; `null` at the end. Opaque. */
	next: string | null,
};

/**  An autocomplete suggestion from addresses of earlier mail. */
export type ContactSuggestion = {
	/**  The name to show and to write (the user's choice, else the most used one). */
	name: string | null,
	/**  The address to write to. */
	email: string,
	/**  Messages the user sent to this address. */
	sent: number,
};

/**
 *  Decision 0039: what the user does with conversation rows. The core answers which messages
 *  it touches ([`ConversationIntent::reach`]); the UI then runs its usual per-message action
 *  (`applyAction` through the outbox, or the marks).
 */
export type ConversationIntent = 
/**  A mail action of the outbox. */
{ kind: "action"; action: MailAction } | 
/**  Pin (`true`) or unpin. */
{ kind: "pin"; pinned: boolean } | { kind: "snooze" } | 
/**  End or clear snoozes. */
{ kind: "unsnooze" } | 
/**  Set or change a task mark (`clear`: take it off). */
{ kind: "task"; clear: boolean } | 
/**  Put on (`true`) or take off the reading list. */
{ kind: "readingList"; on: boolean } | 
/**  Block the sender. */
{ kind: "block" };

/**
 *  Decision 0039: what a conversation row adds to its message (the newest of the conversation in
 *  the listed mailbox), for lists whose rows stay message rows (the sorted inbox with its blocks
 *  and bundles). Same fields as [`ThreadListItem`] without the message.
 */
export type ConversationSummary = {
	/**  The row's message. */
	messageId: MessageId,
	threadId: number | null,
	messageCount: number,
	unreadCount: number,
	lastActivity: number,
	participants: Address[],
	hasAttachments: boolean,
	flagged: boolean,
};

/**
 *  The one event stream from the core to the UI. Internally tagged by `type`.
 * 
 *  The UI never polls: it re-queries what an event says has changed. The engine coalesces
 *  bursts (for example one `messagesChanged` per stored sync window, not per message).
 * 
 *  - `preferencesChanged`: preferences were stored; carries the stored values.
 *  - `accountsChanged`: an account was added or removed; re-query `listAccounts`.
 *  - `accountStatusChanged`: sync state of one account changed; carries the new status.
 *  - `mailboxesChanged`: folder list, roles or counters of an account changed; re-query
 *    `listMailboxes`.
 *  - `messagesChanged`: messages of a mailbox were added, changed or removed; re-query the
 *    visible pages of `listMessages` (counters come with `mailboxesChanged`).
 *  - `newMail`: `count` new unread messages arrived in a mailbox during an incremental sync
 *    (never during the first sync of a mailbox). For notifications; lists react to
 *    `messagesChanged`.
 *  - `messageBodyAvailable`: the body a `getMessage` answered `loading` for is stored; ask again.
 *  - `messageBodyFailed`: that fetch failed.
 *  - `prefetchProgress`: progress of the background prefetch of an account (about once a second).
 *  - `linkActivated`: the user clicked link `index` of the rendering `renderToken`.
 *  - `operationsChanged`: outbox operations of an account were recorded, changed state or were
 *    removed (cancelled, discarded, replaced by a retry). One event per change of the outbox,
 *    so an action on many messages is one event: `operations` carries their complete new
 *    states, `removed` the ids that are gone. Re-query `getOutboxCounts` and a visible
 *    activity page; show a notice for `failed`/`conflict` states of the user's own batches.
 *    The messages' rows change with `messagesChanged`.
 *  - `draftsChanged` (stage 5): local drafts of an account were saved, frozen for sending,
 *    released, got a new server copy (`changed`) or were deleted, sent or discarded
 *    (`removed`). An open composer reloads its draft only if it did not cause the change.
 *  - `outgoingChanged` (stage 5): messages in the outbox view changed state (scheduled,
 *    sending, verifying, unclear, failed, sent); carries their complete states.
 *  - `sendNeedsDecision` (stage 5): it stayed unclear whether a message went out. Ask the user
 *    and answer with `resolveUnclearSend`; nothing is sent again before.
 *  - `inboxChanged` (stage 9): pins, snoozes, tasks or categories changed (a snooze came back,
 *    a sender rule was applied, a local rule pinned something). Re-query the inbox and the
 *    views of pinned, snoozed and task messages; `accountId` is null when several accounts
 *    changed.
 *  - `ruleSkipped` (stage 9): a local rule's action did not run for `count` new messages
 *    (`readOnly`: the account is read-only). Show a notice; nothing else happened.
 *  - `openMessageRequested` (stage 9): the user clicked a system notification; show the
 *    message (in `mailboxId` if given).
 *  - `composeRequested` (stage 9): the system opened a `mailto:` link with the app; open the
 *    composer with these fields and show `request.notices` (a link that sets blind copies, or
 *    tried to set headers that were ignored).
 *  - `mcpAccess` (stage 12): new entries of the AI access log ("Zugriffe"), oldest first.
 *  - `mcpStatusChanged` (stage 12): AI access was switched, its endpoint opened, closed or
 *    failed.
 *  - `signaturesChanged`, `templatesChanged` (stage 10): reload the signature pool or the
 *    templates.
 *  - `aiSettingsChanged` (stage 13, decision 0027): the AI settings changed (any window, or an
 *    account came or went); carries what is usable now. Reload `getAiSettings`.
 *  - `settingsSyncChanged` (stage 11): the settings sync's state, last pass, devices, open
 *    questions or detected folders changed. Data a pass took over from another device comes
 *    with the usual events (`preferencesChanged`, `accountsChanged`, `inboxChanged`, …).
 *  - `uiPreferencesChanged` (stage 8): the UI preferences (shortcuts, text size, recent palette
 *    commands) were stored, here in any window or by the settings sync; carries the stored
 *    values. Every window applies them.
 *  - `savedSearchesChanged` (stage 7, decision 0026): saved searches were created, renamed or
 *    deleted (here or by the settings sync). Reload `listSavedSearches`.
 *  - `updateStatusChanged` (stage 15, decision 0037): the update state changed (checking, up
 *    to date, available, download progress, ready, installing, failed). The setting itself
 *    comes back from the command that changed it; reload `getUpdateInfo` for the rest.
 */
export type CoreEvent = { type: "preferencesChanged"; preferences: Preferences } | { type: "accountsChanged" } | { type: "accountStatusChanged"; accountId: AccountId; status: AccountStatus } | { type: "mailboxesChanged"; accountId: AccountId } | { type: "messagesChanged"; accountId: AccountId; mailboxId: MailboxId } | { type: "newMail"; accountId: AccountId; mailboxId: MailboxId; count: number } | { type: "messageBodyAvailable"; accountId: AccountId; messageId: MessageId } | { type: "messageBodyFailed"; accountId: AccountId; messageId: MessageId; error: IpcError } | { type: "prefetchProgress"; accountId: AccountId; status: PrefetchStatus } | { type: "linkActivated"; renderToken: RenderToken; index: number } | { type: "operationsChanged"; accountId: AccountId; operations: OperationInfo[]; removed: OperationId[] } | { type: "draftsChanged"; accountId: AccountId; changed: DraftId[]; removed: DraftId[] } | { type: "outgoingChanged"; accountId: AccountId; mails: OutgoingMail[] } | { type: "sendNeedsDecision"; accountId: AccountId; mail: OutgoingMail } | { type: "inboxChanged"; accountId: AccountId | null } | { type: "ruleSkipped"; accountId: AccountId; ruleId: RuleId; ruleName: string; reason: RuleSkipReason; count: number } | { type: "openMessageRequested"; accountId: AccountId; mailboxId: MailboxId | null; messageId: MessageId } | { type: "composeRequested"; request: ComposeRequest } | { type: "mcpAccess"; entries: McpAccessEntry[] } | { type: "mcpStatusChanged"; status: McpStatus } | { type: "settingsSyncChanged"; status: SettingsSyncStatus } | 
/**
 *  Stage 13: a running AI request (the id the UI chose): what is sent to whom before each
 *  provider request, the characters received, the end.
 */
{ type: "aiRequest"; requestId: string; phase: AiRequestPhase } | 
/**  Stage 13 (decision 0027): the AI settings or what is usable changed. */
{ type: "aiSettingsChanged"; availability: AiAvailability } | 
/**
 *  Stage 10: the signature pool changed (here or from another device); identity defaults
 *  come with `accountsChanged`.
 */
{ type: "signaturesChanged" } | 
/**  Stage 10: the templates changed (here or from another device). */
{ type: "templatesChanged" } | 
/**  Stage 8: the UI preferences were stored (any window, or another device). */
{ type: "uiPreferencesChanged"; preferences: UiPreferences } | 
/**  Stage 7 (decision 0026): the saved searches changed (here or from another device). */
{ type: "savedSearchesChanged" } | 
/**
 *  Stage 15 (decision 0037): the update state changed (a check, the download's progress,
 *  ready to install, a failure).
 */
{ type: "updateStatusChanged"; status: UpdateStatus };

/**
 *  What the secret of an account is (stage 14). A password (or an app password) by default;
 *  JMAP servers may take an API token instead, which the adapter sends as
 *  `Authorization: Bearer` (Fastmail's JMAP API wants one). Fixed when the account is set up;
 *  kept in the keychain like a password, under a reference that starts with
 *  [`API_TOKEN_CREDENTIAL_PREFIX`].
 */
export type CredentialKind = "password" | 
/**  An API token for a JMAP server (only with [`Protocol::Jmap`]). */
"apiToken";

export type DateSection = {
	kind: DateSectionKind,
	/**  Start of the section (local midnight) in Unix milliseconds. */
	start: number,
};

/**
 *  Date section of a row, in the user's time zone (`docs/DESIGN.md`: Heute, Gestern, Diese
 *  Woche, then by month). Rows of one section are contiguous in the newest-first list.
 */
export type DateSectionKind = 
/**  Today, and anything dated in the future. */
"today" | "yesterday" | 
/**  Earlier this week (from Monday), before yesterday. */
"thisWeek" | 
/**  The calendar month of `start`. */
"month";

/**  Whether the app is the system's handler of `mailto:` links. */
export type DefaultMailApp = {
	/**  Null when the app cannot tell (Windows keeps the choice to itself). */
	isDefault: boolean | null,
	/**
	 *  The app can make itself the default (macOS); otherwise `setDefaultMailApp` opens the
	 *  system's settings (Windows: Settings, Default apps).
	 */
	direct: boolean,
};

/**  What `setDefaultMailApp` did. */
export type DefaultMailAppOutcome = 
/**  The app is the default now. */
"done" | 
/**  The system's settings are open; the user picks the app there. */
"openedSettings" | 
/**
 *  It did not work (for example a build that is not installed as an app); the UI explains
 *  the system's own way (macOS: Mail, Settings, General, "Default email reader").
 */
"manual";

/**  Row height of the list: comfortable (default) or compact. */
export type Density = "comfortable" | "compact";

/**  Result of `exportDiagnostics`. */
export type DiagnosticsExportResult = 
/**  Written to the path the user chose in the system dialog. */
{ kind: "saved"; path: string } | 
/**  The user closed the dialog; nothing was written. */
{ kind: "cancelled" };

/**  Result of server discovery for an email address. Either server may be unknown. */
export type DiscoveryResult = {
	source: DiscoverySource,
	imap: ServerSettings | null,
	smtp: ServerSettings | null,
	providerHint: ProviderHint | null,
	/**
	 *  Stage 14 (decision 0041): a JMAP server found for the address (its session resource
	 *  answered at `https://<host>/.well-known/jmap`, or the domain's autoconfig lists one).
	 *  The setup form offers it as a protocol choice; IMAP stays the default. Left out when
	 *  none was found.
	 */
	jmap?: ServerSettings | null,
	/**
	 *  Security review N-4 (RFC 6186, section 6): found servers that deserve a second look
	 *  before the account is added. Only the online search sets them, never the built-in table.
	 *  Left out when there is none.
	 */
	warnings?: ServerWarnings,
};

/**  Where proposed server settings came from. */
export type DiscoverySource = 
/**  Built-in table of well-known providers (no network). */
"knownProvider" | 
/**  DNS SRV records (`_imaps._tcp`, `_submission._tcp`, RFC 6186). */
"srv" | 
/**  The domain's own autoconfig file (`autoconfig.<domain>`). */
"autoconfig" | 
/**  Nothing found; the user fills in the form. */
"none";

/**
 *  A local draft, as the composer opens it.
 * 
 *  The composer keeps three parts apart (decision 0016): what the user writes (`bodyHtml` or
 *  `bodyText`), the identity's signature (`includeSignature`, switched with the identity) and
 *  the quote of a reply or forward (`quoteHtml`/`quoteText`, read-only in stage 5). The core
 *  puts them together when it saves the draft to the server and when it sends.
 */
export type Draft = {
	id: DraftId,
	accountId: AccountId,
	/**  The sending identity; null when it was deleted (the composer asks for another one). */
	identityId: IdentityId | null,
	kind: DraftKind,
	to: Address[],
	cc: Address[],
	bcc: Address[],
	subject: string,
	format: ComposeFormat,
	/**  Editor HTML of what the user wrote (`format: html`). */
	bodyHtml: string,
	/**  Plain text of what the user wrote (`format: text`). */
	bodyText: string,
	/**  The quoted original as editor HTML (allowlisted) and as plain text with `> `. */
	quoteHtml: string | null,
	quoteText: string | null,
	includeQuote: boolean,
	quotePosition: QuotePosition,
	/**  The identity's text signature goes below what the user wrote. */
	includeSignature: boolean,
	/**
	 *  The signature the composer switched to (stage 10); null = the identity's default for
	 *  this kind of draft (new mail or reply/forward).
	 */
	signatureId: SignatureId | null,
	attachments: DraftAttachment[],
	/**  The message answered or forwarded, while it is still stored locally. */
	originalMessageId: MessageId | null,
	/**  Grows with every save. */
	revision: number,
	state: DraftState,
	server: DraftServerState,
	/**  The send operation while `state` is `sending`. */
	outgoing: OperationId | null,
	/**
	 *  Stage 16 (decision 0033), "Senden und archivieren": once the server accepted the
	 *  message, the answered or forwarded original is archived (through the outbox). Without an
	 *  original it does nothing. Set with `setDraftSendOptions`; a new reply starts with
	 *  [`ComposeSettings::archive_on_reply`].
	 */
	archiveOriginal: boolean,
	/**
	 *  Stage 16: the message asks for a read receipt (`Disposition-Notification-To` with the
	 *  sending identity's address, RFC 8098). The recipient decides whether to send one.
	 */
	requestReadReceipt: boolean,
	/**
	 *  Made from a draft another program saved in the Drafts folder, which the app could not
	 *  take over completely (an image from the web, a part the editor cannot show, a message
	 *  stored only in part) or which had no Message-ID: that copy stays in the folder unchanged,
	 *  and this draft is saved next to it with a Message-ID of its own. The composer says so.
	 */
	originalKept: boolean,
	/**  Unix milliseconds. */
	createdAt: number,
	updatedAt: number,
};

/**
 *  A file attached to a draft. The core keeps its own copy of the bytes (taken when the file
 *  was added), so moving or changing the original file afterwards changes nothing.
 */
export type DraftAttachment = {
	/**  Unique within the draft. */
	id: string,
	/**  Sanitised file name as it will be sent. */
	fileName: string,
	mime: string,
	/**  Decoded bytes. */
	size: number,
	/**
	 *  Set for an inline image (stage 10): the editor shows it as `<img src="cid:…">`, it goes
	 *  out as a part of `multipart/related`, and the attachment list leaves it out.
	 */
	contentId: string | null,
};

/**  Id of a local draft: a UUID, lower case. Stable for the life of the draft. */
export type DraftId = string;

/**  What a draft was started as. */
export type DraftKind = "new" | "reply" | "reply_all" | "forward";

/**  Stage 16 (decision 0033): the per-draft send options (`setDraftSendOptions`). */
export type DraftSendOptions = {
	/**  See [`Draft::archive_original`]. */
	archiveOriginal: boolean,
	/**  See [`Draft::request_read_receipt`]. */
	requestReadReceipt: boolean,
};

/**  Where the draft's copy in the server's Drafts folder stands. */
export type DraftServerState = 
/**  Kept on this device only: writes are off for the account, or it has no Drafts folder. */
"local_only" | 
/**  Changed since the last copy on the server; a copy is saved after a quiet moment. */
"pending" | 
/**  The outbox is putting the newest version on the server. */
"saving" | 
/**  The server has the newest version. */
"saved";

/**  Stage 10: the draft's size against what the account's SMTP server accepts (extension SIZE). */
export type DraftSizeCheck = {
	/**
	 *  Size of the message as it would go out, in bytes (attachments and inline images
	 *  base64-encoded, text, headers): an estimate within a few kilobytes.
	 */
	size: number,
	/**
	 *  The server's limit (SIZE); null when the server announces none or it could not be
	 *  read (offline: then `limitKnown` is false).
	 */
	serverLimit: number | null,
	/**  The server answered (now or earlier in this session). */
	limitKnown: boolean,
	/**  `size` is above `serverLimit`: the server would refuse the message; sending is refused. */
	exceedsServerLimit: boolean,
	/**
	 *  Above [`LARGE_ATTACHMENT_WARNING_BYTES`] of attachments: many providers refuse such
	 *  messages on the receiving side even when this server accepts them.
	 */
	large: boolean,
};

/**  Whether the local draft is a draft or already on its way. */
export type DraftState = 
/**  Being written; saves are accepted. */
"editing" | 
/**
 *  Frozen in the outbox (waiting for the undo delay, sending, failed or unclear); see
 *  [`Draft::outgoing`]. Saves are refused with `send_in_progress` until the user cancels
 *  the send or edits the failed one.
 */
"sending";

/**  A draft in a list (restoring drafts after a crash, the local drafts of an account). */
export type DraftSummary = {
	id: DraftId,
	accountId: AccountId,
	kind: DraftKind,
	subject: string,
	/**  The first To recipients (at most five). */
	to: Address[],
	state: DraftState,
	attachmentCount: number,
	updatedAt: number,
};

/**  What the composer saves: every editable field. Attachments have their own commands. */
export type DraftUpdate = {
	identityId: IdentityId | null,
	to: Address[],
	cc: Address[],
	bcc: Address[],
	subject: string,
	format: ComposeFormat,
	bodyHtml: string,
	bodyText: string,
	includeQuote: boolean,
	quotePosition: QuotePosition,
	includeSignature: boolean,
	/**
	 *  The signature chosen in the composer (stage 10); null or left out = the identity's
	 *  default for this kind of draft.
	 */
	signatureId?: SignatureId | null,
};

/**  Why two contacts may be the same person (or one contact has several names). */
export type DuplicateReason = 
/**  `alice+shop@x` and `alice@x`. */
"plus_address" | 
/**  The same mailbox at the provider (Gmail ignores dots; `googlemail.com`). */
"same_mailbox" | 
/**  The same name at two addresses (`name`). */
"same_name" | 
/**
 *  One address was seen with different names (`names`); the user may pick one with
 *  `setContactName`. `contacts` has one entry.
 */
"names_differ";

/**  What opening a file answers: its id and its name (sanitised, for the window title). */
export type EmlFile = {
	id: EmlFileId,
	name: string,
};

/**
 *  An opened `.eml` file: 32 lowercase hex digits from the operating system's random source,
 *  so one window cannot name another window's file by guessing.
 */
export type EmlFileId = string;

/**
 *  The view of an opened file, like `MessageView` without account and message id: the same
 *  header, body (sanitised HTML with a fresh render token, or text), formats, attachments and
 *  problems. `header.date` is `0` when the file has no readable `Date`.
 */
export type EmlMessageView = {
	fileId: EmlFileId,
	fileName: string,
	header: MessageViewHeader,
	body: MessageBody,
	formats: BodyFormat[],
	attachments: AttachmentInfo[],
	problems: MessageProblem[],
};

/**
 *  Stable, machine-readable error kinds. The UI picks its (translated) text by this code.
 * 
 *  Every code is exported to TypeScript, and the frontend requires an English and a German
 *  text for each one (`ERROR_CODES` in `app/src/services/ipc.ts` fails to compile otherwise):
 *  a new code needs its texts in `app/src/i18n/` in the same change.
 */
export type ErrorCode = "internal" | "invalid_argument" | "not_found" | "database" | "database_too_new" | 
/**  Server rejected user name or password. */
"auth_failed" | 
/**  Certificate chain not trusted by the system (self-signed, unknown CA). */
"cert_untrusted" | 
/**  Certificate is valid, but for another host name. */
"cert_name_mismatch" | 
/**  Certificate expired or not yet valid (check the computer's clock). */
"cert_expired" | 
/**  TLS handshake failed for another reason (protocol version, cipher, broken connection). */
"tls_failed" | 
/**  The server does not offer STARTTLS on this port; it is never used unencrypted. */
"starttls_unavailable" | 
/**  Nothing listens on host and port. */
"connection_refused" | 
/**  Connecting took too long, or the server stopped answering. */
"connection_timeout" | 
/**  The connection broke (network change, server restart). */
"connection_lost" | 
/**  Host name could not be resolved (typo, or offline). */
"dns_failed" | 
/**  The server sent something the app does not understand. */
"protocol" | 
/**  The server refused a command (IMAP NO/BAD). */
"server_rejected" | 
/**  Writing is turned off for this account. */
"read_only" | 
/**  The server lacks something the app requires (IMAP4rev1). */
"unsupported_server" | 
/**  The system keychain refused to store, read or delete the password. */
"keychain" | 
/**  An account with this email address is already set up. */
"account_exists" | 
/**
 *  The account has no folder for this action: archive (`archive`), trash (`delete`), junk
 *  (`spam`) or inbox (`notSpam`). The UI asks which folder to use (`setMailboxRole`) or
 *  offers to create one (`createMailbox`).
 */
"missing_mailbox" | 
/**
 *  The messages lie in the trash, where deleting removes them for good. The UI asks and
 *  then sends the action `deletePermanently`.
 */
"confirmation_required" | 
/**
 *  The action cannot be undone (a permanent delete, a created folder, a move still on its
 *  way or not yet visible in its target folder). Nothing was changed.
 */
"not_undoable" | 
/**  A tag contains spaces or characters IMAP does not allow in keywords. */
"invalid_keyword" | 
/**  The SMTP server refused the message or a recipient; nothing was delivered. */
"send_rejected" | 
/**
 *  The message went out, but the server's confirmation never arrived; it may have been
 *  delivered. Never sent again without the user's decision (`resolveUnclearSend`).
 */
"send_unclear" | 
/**  Stage 5: an address is not valid, or the message has no recipient. */
"invalid_address" | 
/**  Stage 5: the attachments together are larger than the app allows. */
"attachment_too_large" | 
/**
 *  Stage 5: the message is in the outbox (cancel sending to change it), or its submission
 *  started and can no longer be cancelled.
 */
"send_in_progress" | 
/**
 *  Stage 10: a message scheduled for later was due while the app was not running, and
 *  more than an hour has passed: nothing was sent. The user decides (`resolveMissedSend`:
 *  send now, schedule again, or keep it as a draft).
 */
"send_missed" | 
/**
 *  Stage 10: the message is larger than the account's SMTP server accepts (its SIZE
 *  limit); the server would refuse it.
 */
"message_too_large" | 
/**  Stage 11: the passphrase does not unlock the settings sync; nothing was changed. */
"sync_wrong_passphrase" | 
/**  Stage 11: the account holds no settings sync yet (set it up instead of joining). */
"sync_not_set_up" | 
/**  Stage 11: the account holds a settings sync already (join it instead of setting up). */
"sync_already_set_up" | 
/**  Stage 11: the settings sync was reset on another device; enter the new passphrase. */
"sync_key_changed" | 
/**  Stage 11: the settings sync data in the mailbox is damaged or from a newer version. */
"sync_key_invalid" | 
/**  Stage 11: the request needs the settings sync to be on. */
"sync_off" | 
/**
 *  Stage 11: the settings sync is on, but this device has no sync key; enter the
 *  passphrase again.
 */
"sync_key_missing" | 
/**  Stage 13: AI is off, or the function has no provider (or the provider no model). */
"ai_off" | 
/**
 *  Stage 13: a cloud provider needs the user's consent before the first request
 *  (`grantAiConsent`); nothing was sent.
 */
"ai_consent_required" | 
/**  Stage 13: an account involved may not send mail to a cloud provider; nothing was sent. */
"ai_not_permitted" | 
/**  Stage 13: the request was cancelled. */
"ai_cancelled" | 
/**  Stage 13: the provider could not be reached or did not answer in time. */
"ai_unreachable" | 
/**  Stage 13: the provider refused the key (missing, wrong, no access). */
"ai_unauthorized" | 
/**  Stage 13: rate limit or overload at the provider; try later. */
"ai_busy" | 
/**  Stage 13: the model declined the request. */
"ai_refused" | 
/**  Stage 13: any other failure of an AI request (address, model, size, unreadable answer). */
"ai_failed" | 
/**  Stage 9 (decision 0027): the `.eml` file is larger than the app opens. */
"eml_too_large" | 
/**  Stage 9 (decision 0027): the file is empty or has no readable mail header. */
"eml_invalid" | 
/**  Stage 9 (decision 0027): the file is missing, a folder, or could not be read. */
"eml_unreadable" | 
/**  Stage 7 (decision 0026): another saved search has this name. */
"saved_search_exists" | 
/**  Stage 7 (decision 0026): the most saved searches are stored already. */
"saved_search_limit" | 
/**
 *  Stage 16 (decision 0036): the core does not preview this attachment (type, or bytes
 *  that are not what the type says); it can still be saved or opened in the system.
 */
"preview_unsupported" | 
/**  Stage 16 (decision 0036): the attachment is larger than a preview decodes. */
"preview_too_large" | 
/**  Stage 16 (decision 0036): the image or PDF could not be decoded for a preview. */
"preview_damaged" | 
/**  Stage 15 (decision 0037): the update manifest could not be fetched or read. */
"update_check_failed" | 
/**  Stage 15 (decision 0037): the update file could not be downloaded. */
"update_download_failed" | 
/**  Stage 15 (decision 0037): the update's signature is not valid; it was discarded. */
"update_signature_invalid" | 
/**  Stage 15 (decision 0037): installing failed; the installed version is unchanged. */
"update_install_failed" | 
/**  Stage 15 (decision 0037): no update is available or ready for this step. */
"update_not_ready" | 
/**  Stage 14 (decision 0042): this build has no client ID for the provider's sign-in. */
"oauth_unavailable" | 
/**  Stage 14 (decision 0042): the user cancelled the sign-in. */
"oauth_cancelled" | 
/**  Stage 14 (decision 0042): the browser did not come back in time. */
"oauth_timeout" | 
/**  Stage 14 (decision 0042): the provider or the user refused the sign-in. */
"oauth_denied" | 
/**  Stage 14 (decision 0042): the sign-in failed for another reason (see the detail). */
"oauth_failed" | 
/**  Stage 14 (decision 0042): the permission expired or was revoked; sign in again. */
"oauth_sign_in_required" | 
/**  Stage 15: the diagnostics file could not be written where the user chose. */
"diagnostics_write_failed" | 
/**
 *  Stage 14, block D (decision 0041): no JMAP service answers at the address (no session
 *  resource at `/.well-known/jmap`, or one without mail), or it names its endpoints without
 *  encryption.
 */
"jmap_unavailable";

/**  `STATUS` of an event. */
export type EventStatus = "tentative" | "confirmed" | "cancelled";

/**
 *  A template filled for a draft: the composer puts `html` where the cursor is and takes the
 *  subject if its own is empty (the draft itself is not changed).
 * 
 *  Stage 16: `to`, `cc` and `bcc` are the draft's recipients with the template's added (the
 *  composer sets them as they are): the draft's stay first and unchanged; a template address
 *  that is already in any field of the draft is not added again; at most `MAX_RECIPIENTS`
 *  together. `recipientsAdded` counts the addresses the template added.
 */
export type FilledTemplateInfo = {
	subject: string,
	/**  Editor HTML. */
	html: string,
	text: string,
	problems: TemplateFillProblem[],
	to: Address[],
	cc: Address[],
	bcc: Address[],
	recipientsAdded: number,
};

/**  `getFirstStart` and `finishFirstStart`. */
export type FirstStart = {
	/**  Show the guided first start now: it never ended and there is no account yet. */
	show: boolean,
	/**  How it ended; `None` while it is still to be shown. */
	outcome: FirstStartOutcome | null,
};

/**  What the UI may end the first start with (`finishFirstStart`). `NotNeeded` is the core's own. */
export type FirstStartEnd = "completed" | "skipped";

/**
 *  How the guided first start ended. Stored per device (setting `first_start`, never synced:
 *  accounts and the update question belong to this computer).
 */
export type FirstStartOutcome = 
/**  Walked through to the last step. */
"completed" | 
/**  "Skip setup" on one of the steps. */
"skipped" | 
/**
 *  The installation already had an account when the core was first asked (it predates the
 *  first start), so it was never shown.
 */
"notNeeded";

/**
 *  Local row id of an identity (`identity.id`). Not stable across devices (the settings sync
 *  uses the identity's UUID). Exported since stage 7 (identities in the settings).
 */
export type IdentityId = number;

/**  A sender identity of an account over IPC. */
export type IdentityInfo = {
	id: IdentityId,
	accountId: AccountId,
	email: string,
	name: string,
	replyTo: string | null,
	isDefault: boolean,
};

/**  Fields of a new or changed identity. */
export type IdentityInput = {
	email: string,
	name: string,
	replyTo: string | null,
};

/**  The default signatures of an identity. */
export type IdentitySignatureDefaults = {
	identityId: IdentityId,
	/**  For new mails; null = none. */
	newSignature: SignatureId | null,
	/**  For replies and forwards; null = none. */
	replySignature: SignatureId | null,
};

/**
 *  Keyset cursor of the inbox: the message cursor plus the bundles the current date section
 *  has started (opaque; pass it back unchanged).
 */
export type InboxCursor = {
	before: ListCursor,
	/**  Serialised bundle state, null when categories are off or nothing is open. */
	bundles: string | null,
};

/**  A filtered inbox list ("Alle anzeigen", a click on a bundle's category). */
export type InboxFilter = 
/**  Messages of one category (after the user's sender rules). */
{ kind: "category"; category: MessageCategory } | 
/**  Messages of important senders. */
{ kind: "priority" } | 
/**  Stage 16: unread messages only ("Nur ungelesene"), newest first. */
{ kind: "unread" };

/**  One page of the inbox. */
export type InboxPage = {
	rows: InboxRow[],
	/**  Null on the last page. */
	nextCursor: InboxCursor | null,
	/**  Pinned, returned and priority messages; only on the first page (no cursor given). */
	top: InboxTop | null,
	/**
	 *  Categories are on: notifications and newsletters are bundled. Off: the rows are purely
	 *  chronological.
	 */
	categories: boolean,
	/**
	 *  Decision 0039 (`listInboxConversations`): every message of the rows and of `top` stands
	 *  for its conversation; one summary per such message. Empty for `listInbox`.
	 */
	conversations: ConversationSummary[],
};

/**  One row of the inbox list. */
export type InboxRow = 
/**
 *  A message of its own (people, important senders, and everything when categories are
 *  off).
 */
{ kind: "message"; item: MessageListItem; section: DateSection } | 
/**
 *  Notifications or newsletters of one date section as one row; it stands where its newest
 *  member is. `members` are the members on this page, newest first; a click expands them in
 *  place. A bundle with one member may be drawn like a normal row.
 */
{ kind: "bundle"; summary: BundleSummary; section: DateSection; members: MessageListItem[] } | 
/**
 *  More members of a bundle an earlier page started: append them to that row (same
 *  `summary.key`) and replace its summary with this one.
 */
{ kind: "more"; summary: BundleSummary; members: MessageListItem[] };

/**  Which inbox a view shows. */
export type InboxScope = 
/**  One mailbox, usually an account's inbox. */
{ kind: "mailbox"; mailboxId: MailboxId } | 
/**  The unified inbox, or the inboxes of a group (hidden accounts left out). */
{ kind: "unified"; view: UnifiedView };

/**  The inbox settings (stage 9). Device settings, stored in the `setting` table. */
export type InboxSettings = {
	/**  Off: no bundles and no priority block, the inbox is purely chronological. */
	categories?: boolean,
	bundleNotifications?: boolean,
	bundleNewsletters?: boolean,
};

/**  What stands above the date sections. Only on the first page. */
export type InboxTop = {
	/**
	 *  Pinned messages of the scope, newest first (at most [`MAX_TOP_PINNED`]). They are not
	 *  repeated in the rows.
	 */
	pinned: MessageListItem[],
	/**
	 *  Snoozed messages that came back, most recently returned first (at most
	 *  [`MAX_TOP_RETURNED`]). Not repeated in the rows; they stay here until the user clears
	 *  the mark (`clearSnooze`), snoozes them again or they leave the inbox.
	 */
	returned: MessageListItem[],
	/**
	 *  The newest messages of important senders (at most [`PRIORITY_PREVIEW`]); they also
	 *  stand in the rows, never bundled. Empty when categories are off.
	 */
	priority: MessageListItem[],
	/**  All messages of important senders in the scope ("Alle anzeigen (n)"). */
	priorityTotal: number,
	priorityUnread: number,
};

/**  Stage 10: what adding inline images to a draft did. */
export type InlineImagesAdded = {
	draft: Draft,
	/**
	 *  The new images in the order of the files: the editor inserts
	 *  `<img src="cid:{contentId}">` for each and shows it with `inlineImageData`.
	 */
	added: DraftAttachment[],
};

/**  The error as it crosses the IPC bridge: `{ code, message, detail }`. */
export type IpcError = {
	code: ErrorCode,
	/**  English fallback text; the UI shows an i18n text chosen by `code`. */
	message: string,
	/**  Technical detail, never secrets. */
	detail: string | null,
};

export type LanguagePreference = "system" | "en" | "de";

/**  Answer of `describeLink`: what the user confirms before the system browser opens. */
export type LinkInfo = {
	/**  The real target, complete, for display. */
	target: string,
	/**  Lower-case scheme (`https`, `http`, `mailto`, ...). */
	scheme: string,
	/**  Host in Unicode form; null for `mailto` and hostless URLs. */
	host: string | null,
	/**  Visible link text, white space collapsed, at most 200 characters; empty for images. */
	text: string,
	warnings: LinkWarning[],
	/**  Only `http`, `https` and `mailto` can be opened. */
	openable: boolean,
};

/**
 *  What `openLink` did (stage 10): opened the link in the system (`http`, `https`), or, for a
 *  `mailto:` link in a mail, nothing yet: the UI opens its own composer with the request
 *  (whether or not this app is the system's default mail app).
 */
export type LinkOpened = { kind: "opened" } | { kind: "compose"; request: ComposeRequest };

/**  Why a link deserves a second look. */
export type LinkWarning = 
/**  The link text names another domain than the target. */
{ kind: "domainMismatch"; shownDomain: string; targetDomain: string } | 
/**
 *  The host mixes scripts or uses look-alike characters (IDN homograph); `ascii_host` is
 *  its punycode form.
 */
{ kind: "confusableHost"; asciiHost: string } | 
/**  The host is a bare IP address. */
{ kind: "ipAddressHost" } | 
/**  The URL carries a user name or password (`https://bank.example@evil.example/`). */
{ kind: "credentialsInUrl" } | 
/**  A scheme other than http, https and mailto; the link cannot be opened. */
{ kind: "unsupportedScheme" };

/**
 *  Keyset cursor of a message list: pass `nextCursor` of one page back to get the next page.
 *  Opaque to the UI; today it is the [`MessageId`] of the last item of the page.
 */
export type ListCursor = number;

/**  What the user asks for. One action on many messages is one batch ([`BatchId`]). */
export type MailAction = { type: "markRead" } | { type: "markUnread" } | { type: "flag" } | { type: "unflag" } | { type: "addKeyword"; keyword: string } | { type: "removeKeyword"; keyword: string } | 
/**
 *  Stage 14 (decision 0034): adds a Gmail label (`STORE +X-GM-LABELS`). Only on Gmail
 *  accounts ([`ActionError::LabelsUnsupported`] elsewhere); the name is checked with
 *  [`crate::is_valid_label`] ([`ActionError::InvalidLabel`]).
 */
{ type: "addLabel"; label: string } | 
/**  Stage 14: removes a Gmail label (`STORE -X-GM-LABELS`). */
{ type: "removeLabel"; label: string } | 
/**
 *  Moves to the mailbox with the role `archive`. On Gmail (decision 0034) it removes the
 *  inbox label instead (`STORE -X-GM-LABELS (\Inbox)`), with no archive folder needed. Without one the action fails with
 *  [`ActionError::MissingMailbox`], so the UI can ask which mailbox to use (then
 *  `setMailboxRole`) or whether to create one (an operation of its own).
 */
{ type: "archive" } | 
/**
 *  Moves to the trash. Messages that already lie in the trash are only deleted with
 *  [`MailAction::DeletePermanently`]; `Delete` on them fails with
 *  [`ActionError::ConfirmationRequired`].
 */
{ type: "delete" } | 
/**
 *  Deletes for good (EXPUNGE). The UI asks before sending it; this action is the explicit
 *  confirmation the core requires.
 */
{ type: "deletePermanently" } | 
/**  Moves to another mailbox of the same account. */
{ type: "move"; target: MailboxId } | 
/**  Moves to the mailbox with the role `junk`. */
{ type: "spam" } | 
/**  Moves messages from the junk mailbox to the inbox; others are left alone. */
{ type: "notSpam" };

/**  A local rule: runs on new mail in the inbox while the app runs (labelled so in the UI). */
export type MailRule = {
	id: RuleId,
	name: string,
	enabled: boolean,
	/**  All conditions must hold (`true`) or any (`false`). No condition: every message. */
	matchAll: boolean,
	conditions: RuleCondition[],
	actions: RuleAction[],
	/**  Later rules are not evaluated for a message this rule matched. */
	stop: boolean,
	/**  Order: lower runs first. */
	position: number,
};

/**  A mailbox as the UI sees it (sidebar, folder tree). */
export type Mailbox = {
	id: MailboxId,
	accountId: AccountId,
	/**  Full decoded path, for example `Projekte/2026`. The inbox is `INBOX`. */
	path: string,
	/**  Last segment of `path`, for the tree. The UI shows a translated name for roles. */
	name: string,
	/**  Hierarchy delimiter, null if the server has a flat namespace. */
	delimiter: string | null,
	parentId: MailboxId | null,
	role: MailboxRole,
	roleSource: RoleSource,
	/**  `false` for placeholders that cannot hold messages (`\Noselect`, `\NonExistent`). */
	selectable: boolean,
	/**  Unread messages stored locally. */
	unread: number,
	/**  Messages stored locally (grows during the first sync). */
	total: number,
	/**
	 *  Stage 16: a favourite (on top of the sidebar and in the palette), with its position
	 *  among the favourites (ascending). Absent when not a favourite.
	 */
	favoritePosition?: number | null,
	/**
	 *  Stage 16: the colour the user gave the folder (index into the account colour palette;
	 *  always shown with the name). Absent when none.
	 */
	color?: AccountColor | null,
};

/**  Local row id of a mailbox (`mailbox.id`). Not stable across devices. */
export type MailboxId = number;

/**  What a mailbox is for. At most one mailbox per account has each role except `custom`. */
export type MailboxRole = "inbox" | "sent" | "drafts" | "archive" | "trash" | "junk" | 
/**  Virtual folder with every message (Gmail "All Mail", `\All`). */
"all" | 
/**  Virtual folder with flagged messages (Gmail "Starred", `\Flagged`). */
"flagged" | 
/**  An ordinary folder. */
"custom";

/**  A field of a `mailto:` link that a [`MailtoNotice`] refers to. */
export type MailtoField = "to" | "cc" | "bcc" | "subject" | "body" | "in_reply_to";

/**
 *  Something about a `mailto:` link the composer shows as a hint. Values are copied from the
 *  link (decoded, on one line, cut to a few hundred characters).
 */
export type MailtoNotice = 
/**
 *  The link adds blind copies: the user must see them before sending. Always the first
 *  notice when present.
 */
{ kind: "bcc_present" } | 
/**
 *  A header field outside the allowlist (`to`, `cc`, `bcc`, `subject`, `body`,
 *  `in-reply-to`), for example `from`, `reply-to` or `x-mailer`. Never applied; `name` in
 *  lower case.
 */
{ kind: "header_ignored"; name: string } | 
/**
 *  `subject`, `body` or `in-reply-to` came more than once; only the first usable one is
 *  used.
 */
{ kind: "duplicate_ignored"; field: MailtoField } | 
/**
 *  Not a usable address (left out). Quoted local parts (`"not@me"@example.org`) are
 *  decoded but not supported by the composer, so they end up here too.
 */
{ kind: "address_invalid"; value: string } | 
/**  `in-reply-to` is not one valid Message-ID (left out). */
{ kind: "message_id_invalid"; value: string } | 
/**
 *  The field was over its limit and was cut (subject, body) or recipients were left out
 *  (To, Cc, Bcc: more than `MAX_RECIPIENTS` together).
 */
{ kind: "truncated"; field: MailtoField } | 
/**  Percent-encoded bytes were not valid UTF-8; they were replaced with U+FFFD. */
{ kind: "invalid_encoding"; field: MailtoField } | 
/**
 *  Control characters were removed: line breaks in the subject became spaces, characters
 *  other than line breaks and tabs were dropped from the body.
 */
{ kind: "control_characters_removed"; field: MailtoField } | 
/**  More hints of the kinds above that carry a value than are listed. */
{ kind: "notices_omitted"; count: number };

/**
 *  When the reading pane marks an opened message as read (stage 4). The UI does the marking
 *  (an ordinary `markRead` action), and only for accounts with `writesEnabled`; read-only
 *  accounts mark nothing.
 */
export type MarkReadOnOpen = 
/**  As soon as the message is shown. */
"immediately" | 
/**  After it was shown for [`MARK_READ_DELAY_MS`] without the selection changing. */
"afterDelay" | "never";

/**  The accounts a view of pinned, snoozed or task messages covers. */
export type MarkScope = 
/**  Every visible account. */
{ kind: "all" } | 
/**  The visible accounts of a group. */
{ kind: "group"; groupId: AccountGroupId } | 
/**  One account (also a hidden one). */
{ kind: "account"; accountId: AccountId };

/**  One entry of the access log: metadata only, never arguments or content. */
export type McpAccessEntry = {
	id: McpAccessId,
	/**  Unix milliseconds. */
	at: number,
	/**  Null for a connection refused before the client was known. */
	clientId: string | null,
	/**  The client's name at that moment. */
	clientName: string | null,
	/**  The tool called; null for a refused connection. */
	tool: McpTool | null,
	/**  Messages whose data the answer contained (a created draft counts as one). */
	messages: number,
	outcome: McpAccessOutcome,
	/**  Set for a refused connection. */
	refusal: McpRefusal | null,
};

/**  Id of an access log entry; grows with every entry. The cursor of `listMcpAccess`. */
export type McpAccessId = number;

/**  How a logged access ended. */
export type McpAccessOutcome = 
/**  The tool ran and answered. */
"ok" | 
/**  The tool ran and reported an error (bad argument, unknown id, app error). */
"error" | 
/**  Not run (not allowed, rate limit, timeout), or a connection was refused. */
"refused";

/**  One page of the access log, newest first. */
export type McpAccessPage = {
	entries: McpAccessEntry[],
	/**  Pass as `before` for the next page; null on the last page. */
	nextCursor: McpAccessId | null,
};

/**  What AI clients may do with one account. Every account starts `hidden`. */
export type McpAccountAccess = 
/**  Invisible to every tool, also to the search. */
"hidden" | 
/**  Listed, searchable, readable (bodies are read with `BODY.PEEK`: nothing becomes read). */
"read" | 
/**
 *  Also "create draft". Without writes on for the account the draft stays in the app on
 *  this device (`localOnly`).
 */
"read_and_drafts";

/**  The access level of one account. */
export type McpAccountShare = {
	accountId: AccountId,
	access: McpAccountAccess,
};

/**  One configuration to copy. */
export type McpClientConfig = {
	kind: McpClientKind,
	/**
	 *  Where it goes: a file path with `~` or `%APPDATA%`, `terminal` for Claude Code, or a
	 *  short hint for LM Studio (shown as is).
	 */
	location: string,
	/**
	 *  JSON for the configuration files, a command line for Claude Code. Contains the token
	 *  when it comes from `createMcpClient`, the placeholder `<token>` otherwise.
	 */
	content: string,
	/**
	 *  Claude Code only: the same command with `MAIL_MCP_TOKEN_FILE` (a file in the home
	 *  directory that holds the token) instead of the token, so the token ends up in no shell
	 *  history and no process list. Never contains the token.
	 */
	tokenFileContent: string | null,
	/**  The client's documentation of the format. */
	source: string,
};

/**
 *  A new client (`createMcpClient`): its token and the configurations with the token filled
 *  in. Shown once; the app cannot show the token again (a lost token means a new client).
 */
export type McpClientCreated = {
	client: McpClientInfo,
	/**  `mcp1_<client id>_<key>`; the environment variable `MAIL_MCP_TOKEN` of the client. */
	token: string,
	configs: McpClientConfig[],
};

/**
 *  A registered AI client. Its key lives in the system keychain; the app shows the token only
 *  once, right after creating the client.
 */
export type McpClientInfo = {
	/**  32 lowercase hex digits; not secret (it names the client in the access log). */
	clientId: string,
	/**  Chosen by the user. */
	name: string,
	/**  Unix milliseconds. */
	createdAt: number,
	/**  Set once revoked: the token no longer works, the key is gone from the keychain. */
	revokedAt: number | null,
	/**  The last tool call or connection attempt of this client. */
	lastUsedAt: number | null,
};

/**  The AI clients with a ready-made configuration. */
export type McpClientKind = "claude_desktop" | "claude_code" | "cursor" | "lm_studio";

/**
 *  Result of "test connection": the app starts its helper program like an AI client would,
 *  with a temporary client of its own, and asks it for the tools and the shared accounts.
 */
export type McpConnectionTest = {
	ok: boolean,
	problem: McpTestProblem | null,
	refusal: McpRefusal | null,
	/**  The helper that was started. */
	helperPath: string | null,
	/**  MCP protocol version the helper agreed on. */
	protocolVersion: string | null,
	/**  Tools the helper listed (from the app when it was reached). */
	tools: McpTool[],
	/**  Accounts visible to AI clients right now. */
	sharedAccounts: number,
	/**  Technical detail for a failure (English, from the app or the helper; never mail data). */
	detail: string | null,
	durationMs: number,
};

/**  The helper program `mail-mcp` that AI clients start. */
export type McpHelperInfo = {
	/**  Absolute path, as the client configurations contain it. */
	path: string | null,
	/**
	 *  `path` with the user's home directory written as `~` (`~/Applications/…`), for showing
	 *  on the settings page: a screenshot or a shared screen does not carry the user name.
	 */
	displayPath: string | null,
	/**  The file exists. */
	found: boolean,
	/**
	 *  The app runs from a place that changes (a disk image, macOS App Translocation): the
	 *  path in a client configuration would stop working. The UI asks to move the app first.
	 */
	unstableLocation: boolean,
};

/**  What the local endpoint is doing. */
export type McpHostState = 
/**  MCP is off: no socket or pipe exists, nothing can connect. */
"stopped" | 
/**  Waiting for the helper program of an AI client. */
"listening" | 
/**
 *  MCP is on, but the endpoint could not be opened (`McpStatus::error` says why). Tried
 *  again at the next settings change.
 */
"failed";

/**  Why the app refused a connection of a helper program. */
export type McpRefusal = 
/**  The helper speaks another IPC version (app and helper from different releases). */
"unsupported_protocol" | 
/**  MCP is off. */
"disabled" | 
/**  The client was never registered, or was revoked. */
"unknown_client" | 
/**  The token's key is wrong. */
"bad_proof" | 
/**  The helper sent something unreadable. */
"malformed" | 
/**  The handshake took too long. */
"timeout" | 
/**  Too many AI clients at once. */
"too_many_connections";

/**  Everything the settings page "AI over MCP" shows. */
export type McpSettingsInfo = {
	enabled: boolean,
	/**  Every account, oldest first, with its access level (`hidden` when never shared). */
	accounts: McpAccountShare[],
	/**  Registered clients, newest first; revoked ones stay listed with `revokedAt`. */
	clients: McpClientInfo[],
	status: McpStatus,
};

/**
 *  The setup help without a token (`getMcpSetup`): helper path, endpoint and the
 *  configurations with the placeholder `<token>`.
 */
export type McpSetup = {
	helper: McpHelperInfo,
	endpoint: string | null,
	configs: McpClientConfig[],
};

/**  State of AI access, for the settings page and `mcpStatusChanged`. */
export type McpStatus = {
	/**  The master switch. */
	enabled: boolean,
	state: McpHostState,
	/**  Where the app listens (socket path on macOS, pipe name on Windows); null until known. */
	endpoint: string | null,
	/**
	 *  `endpoint` with the home directory written as `~`, for showing (see
	 *  [`McpHelperInfo::display_path`]).
	 */
	endpointDisplay: string | null,
	/**
	 *  Why the endpoint could not be opened (`failed`); technical text from the app, never
	 *  from a mail.
	 */
	error: string | null,
	helper: McpHelperInfo,
};

/**  What went wrong in "test connection". */
export type McpTestProblem = 
/**  MCP is off; turn it on first. */
"disabled" | 
/**
 *  The helper program is not where the configurations say (a development build without
 *  `cargo build -p mail-mcp`, or a damaged installation).
 */
"helper_missing" | 
/**  The helper program did not start, crashed or did not speak MCP. */
"helper_failed" | 
/**  The app could not open its endpoint (`McpStatus::error`). */
"endpoint_failed" | 
/**  The helper started but could not reach the app. */
"unreachable" | 
/**  The app refused the helper (`refusal`). */
"refused" | 
/**  No answer in time. */
"timeout";

/**  The tools of the MCP server (fixed in `mail-mcp`; nothing sends, deletes, moves or marks). */
export type McpTool = "list_accounts" | "list_mailboxes" | "search_messages" | "list_messages" | "read_message" | "read_thread" | "create_draft";

/**
 *  Outbox state of a message as its list row shows it (stage 4). If several operations touch
 *  the message, the one that needs the user wins: `failed`, then `conflict`, then `pending`.
 */
export type MessageActivity = 
/**  A change waits for the server (`queued` or `in_flight`); the row already shows it. */
"pending" | 
/**  A change failed and was reverted locally. The activity view offers retry and discard. */
"failed" | 
/**
 *  The message was changed elsewhere meanwhile and the server's state was kept. The
 *  activity view explains it.
 */
"conflict";

/**  The body as the UI shows it. */
export type MessageBody = 
/**
 *  Sanitized HTML for `<iframe sandbox="allow-same-origin" srcdoc=...>`. Starts with the
 *  mandatory meta CSP; every `href` is a placeholder of `render_token`; external images are
 *  replaced unless remote content was loaded.
 */
{ kind: "html"; srcdoc: string; renderToken: RenderToken; 
/**  External images and styles that were blocked (0 when `remote_loaded`). */
blockedRemote: number; remoteLoaded: boolean } | 
/**
 *  Plain text for the app's own theme. Links are separate segments, opened through the same
 *  check as HTML links (`describeLink` with this `render_token`).
 */
{ kind: "text"; segments: TextSegment[]; renderToken: RenderToken } | 
/**
 *  Not stored locally; a fetch is running. `messageBodyAvailable` or `messageBodyFailed`
 *  follows; then ask again.
 */
{ kind: "loading" } | 
/**  Not stored locally and cannot be fetched now. */
{ kind: "unavailable"; reason: BodyUnavailableReason; 
/**  Details for `fetchFailed`, null otherwise. */
error: IpcError | null };

/**  The category of a message in the inbox. */
export type MessageCategory = 
/**  Written by a person (the default when nothing points to a program or a list). */
"person" | 
/**
 *  Written by a program for the user: notifications, confirmations, automatic replies,
 *  delivery reports.
 */
"notification" | 
/**  Mass mail: newsletters, mailing lists, marketing. */
"newsletter";

/**  "Why here?" for one message, and the keys an "always as …" can use. */
export type MessageCategoryInfo = {
	messageId: MessageId,
	/**  Null while the message is not classified yet. */
	decision: CategoryDecision | null,
	/**
	 *  The normalised sender address, its domain and the list, for "always as …" (each null
	 *  when the message has none).
	 */
	address: SenderKey | null,
	domain: SenderKey | null,
	list: SenderKey | null,
};

/**
 *  What the reading pane shows besides the body (stage 9): the category ("Why here?"),
 *  unsubscribing, calendar invitations.
 */
export type MessageExtras = {
	category: MessageCategoryInfo,
	/**  Empty when the message offers nothing. */
	unsubscribe: UnsubscribeOptions,
	/**
	 *  Invitations of the `text/calendar` parts (`partId` for `openInvite`). Empty while the
	 *  body is not stored whole (`bodyComplete` false): ask again after
	 *  `messageBodyAvailable`.
	 */
	invites: CalendarInviteInfo[],
	bodyComplete: boolean,
};

/**
 *  Local id of a message (`message.id`): its sort date in Unix seconds, or the next free number
 *  above it (decision 0003). Larger is newer. Below 2^33, so exact as a JavaScript number.
 */
export type MessageId = number;

/**  One row of the message list. */
export type MessageListItem = {
	id: MessageId,
	accountId: AccountId,
	mailboxId: MailboxId,
	/**  First `From` address, null if none. */
	from: Address | null,
	/**  `To` addresses, for lists of sent mail and drafts. */
	to: Address[],
	/**  Empty if the message has no subject. */
	subject: string,
	/**  Sort date in Unix milliseconds. */
	date: number,
	unread: boolean,
	flagged: boolean,
	answered: boolean,
	draft: boolean,
	hasAttachments: boolean,
	/**  Keywords as stored (for example `$Forwarded`), see [`Flags::keywords`]. */
	keywords: string[],
	/**
	 *  Start of the text, white space collapsed, at most 256 characters; null until the body
	 *  was parsed (opened or prefetched).
	 */
	preview: string | null,
	/**
	 *  Outbox state of a change to this message, for a small symbol in the row. Absent when
	 *  nothing is pending or needs the user (most rows), so pages stay small.
	 */
	activity?: MessageActivity | null,
	/**
	 *  Stage 9: the category after the user's sender rules; null until the message is
	 *  classified (treat it as a person's).
	 */
	category: MessageCategory | null,
	/**  Stage 9: the sender, domain or list is marked important ("Priority" block). */
	important: boolean,
	/**  Stage 9: pinned. */
	pinned: boolean,
	/**  Stage 9: snoozed (waiting, or came back). Absent when not snoozed. */
	snooze?: SnoozeMark | null,
	/**  Stage 9: marked as a task. Absent when not. */
	task?: TaskMark | null,
	/**  Stage 16: on the reading list ("Zum Lesen"). Absent when not. */
	readingList?: boolean,
};

/**  One page of a message list, newest first. */
export type MessagePage = {
	items: MessageListItem[],
	/**  Pass to the next call to continue; null on the last page. */
	nextCursor: ListCursor | null,
};

/**  Defects of a message that the reading pane mentions. */
export type MessageProblem = 
/**  The MIME structure is damaged (missing boundary, truncated); shown as far as readable. */
"brokenStructure" | 
/**  A text part declared an unknown charset; decoded with replacement characters. */
"unknownCharset" | 
/**  A part's transfer encoding is broken; it is shown raw or left out. */
"undecodablePart" | 
/**  No readable text part (only attachments, or empty). */
"noContent" | 
/**  The message could not be parsed at all and is shown as raw text. */
"rawFallback";

/**  A message in one mailbox, as the list shows it (`MessageListItem::mailbox_id` and `id`). */
export type MessageRef = {
	mailboxId: MailboxId,
	messageId: MessageId,
};

/**  What `getMessage` returns: everything the reading pane shows. */
export type MessageView = {
	id: MessageId,
	/**  For the account color. */
	accountId: AccountId,
	header: MessageViewHeader,
	body: MessageBody,
	/**
	 *  Formats the message can be shown in (`html`, `text`, or both). Switching is another
	 *  `getMessage` with that format; it is served locally.
	 */
	formats: BodyFormat[],
	/**  Real attachments (not the inline images the HTML shows), in message order. */
	attachments: AttachmentInfo[],
	/**
	 *  A large message of which only the text parts are stored; attachments are fetched when
	 *  saved or opened.
	 */
	partial: boolean,
	/**  Defects found while parsing; the UI shows a hint. Empty for well-formed mail. */
	problems: MessageProblem[],
};

/**  Header of the reading pane. Addresses decoded (RFC 2047), groups flattened. */
export type MessageViewHeader = {
	from: Address[],
	to: Address[],
	cc: Address[],
	/**  Only known for mail the user sent (Sent, Drafts). */
	bcc: Address[],
	replyTo: Address[],
	/**  Sort date in Unix milliseconds, as in the list. */
	date: number,
	/**  Empty if the message has no subject. */
	subject: string,
};

/**  Stage 10: the user's answer to a scheduled send that was missed while the app was off. */
export type MissedSendDecision = 
/**  Send it now (after the usual undo delay). */
{ kind: "send_now" } | 
/**  Schedule it again for this time (Unix ms, in the future). */
{ kind: "reschedule"; sendAt: number } | 
/**  Take it out of the outbox; it becomes an editable draft again. */
{ kind: "keep_as_draft" };

/**  How a new draft starts. */
export type NewDraft = 
/**
 *  An empty message from the account (its default identity unless `identityId`), optionally
 *  to someone already (a `mailto:` click, "write to" in a contact).
 */
{ kind: "new"; accountId: AccountId; identityId: IdentityId | null; to: Address[] } | 
/**  An answer to the sender of `messageId`, from the identity the message went to. */
{ kind: "reply"; messageId: MessageId; language: QuoteLanguage } | 
/**  An answer to the sender and every other recipient except the user's own addresses. */
{ kind: "reply_all"; messageId: MessageId; language: QuoteLanguage } | 
/**  The message with its attachments, to new recipients. */
{ kind: "forward"; messageId: MessageId; language: QuoteLanguage } | 
/**
 *  Stage 10: a new message with every field of a [`crate::ComposeRequest`] (a `mailto:`
 *  link, `openLink` → `compose`): recipients, subject, plain-text body, and `In-Reply-To`
 *  (with `References`) for threading. From the account's default identity unless
 *  `identityId`. The request's notices are the UI's to show; they are not stored.
 */
{ kind: "compose"; accountId: AccountId; identityId: IdentityId | null; request: ComposeRequest } | 
/**
 *  Stage 10: the whole message as an attachment (`message/rfc822`, `<subject>.eml`), to
 *  new recipients; nothing quoted. Needs the complete original (`invalid_argument` for a
 *  large message stored only in part: forward it inline instead).
 */
{ kind: "forward_as_attachment"; messageId: MessageId; language: QuoteLanguage };

/**  Notification settings (device settings). */
export type NotificationSettings = {
	/**  Off: no notification at all. */
	enabled?: boolean,
	newMail?: boolean,
	categories?: NotifyCategories,
	failedSends?: boolean,
	snoozes?: boolean,
	quietHours?: QuietHours,
	/**
	 *  Show "New message" instead of sender and subject. The system decides separately whether
	 *  previews appear on the lock screen (macOS: Notifications, "Show previews"; Windows:
	 *  Notifications, "Show notifications on the lock screen").
	 */
	hideContent?: boolean,
	/**  Accounts whose new mail is never announced. */
	mutedAccounts?: AccountId[],
	badge?: BadgeMode,
	/**  Stage 16: the sound notifications make (settings stored before have the default). */
	sound?: NotificationSound,
};

/**
 *  Stage 16: the sound of notifications. One setting for all devices (it is part of the synced
 *  `notifications.settings`), with a choice per platform since the systems have different
 *  sounds. Quiet hours drop the notification and with it the sound.
 */
export type NotificationSound = {
	/**  Off: every notification is silent. */
	enabled?: boolean,
	/**  One of [`MACOS_SOUNDS`]; an unknown name plays `Default`. */
	macos?: string,
	/**  One of [`WINDOWS_SOUNDS`]; an unknown name plays `Default`. */
	windows?: string,
	/**  Accounts whose notifications show without a sound. */
	silentAccounts?: AccountId[],
};

/**  The notification sounds of this platform, for the settings page. */
export type NotificationSoundChoices = {
	platform: SoundPlatform,
	/**  The names to offer, `Default` first; empty on other platforms. */
	sounds: string[],
};

/**
 *  The texts of system notifications, in the UI's language. The UI sends them from
 *  `app/src/i18n/` at start and when the language changes (`setNotificationTexts`); until then
 *  the English defaults apply. `{count}` is replaced by a number, `{subject}` by a subject.
 */
export type NotificationTexts = {
	/**  Title when content is hidden, or for one message without a sender. */
	newMessage?: string,
	/**  Title for several messages at once. */
	newMessages?: string,
	/**  Body when the subject is empty. */
	noSubject?: string,
	/**  Title of a failed send; the body is the subject. */
	sendFailed?: string,
	/**  Title of a returned snooze; the body is the subject (or hidden). */
	snoozeDue?: string,
};

/**
 *  Which new mail is announced (by category after the user's rules; a rule's `notify` action
 *  overrides).
 */
export type NotifyCategories = {
	people?: boolean,
	/**  Important senders, whatever their category. */
	priority?: boolean,
	notifications?: boolean,
	newsletters?: boolean,
};

/**
 *  Which sign-ins this build offers: a provider needs a client ID configured when the app was
 *  built. Without one the setup hides the button and says that this build cannot sign in there.
 */
export type OAuthAvailability = {
	microsoft: boolean,
	google: boolean,
};

/**
 *  The texts of the page the browser shows when it comes back to the app (the UI's
 *  translations; the core escapes them). Plain text, no markup.
 */
export type OAuthPageTexts = {
	/**  Title of the page (the app's name, for example). */
	title: string,
	/**  Shown when the sign-in went through: "You can close this window and return to the app." */
	done: string,
	/**  Shown when the provider refused or something failed. */
	failed: string,
};

/**
 *  A provider whose accounts sign in through its own login page (OAuth 2.0) instead of a
 *  password. Stored as part of the account's keychain reference (`oauth:<provider>:…`).
 */
export type OAuthProvider = 
/**  Microsoft 365 and Outlook.com (Microsoft Entra, authority `common`). */
"microsoft" | 
/**  Gmail and Google Workspace. */
"google";

/**  Result of `openAttachment`. */
export type OpenAttachmentResult = 
/**  Handed to the system's default app. */
{ kind: "opened" } | 
/**
 *  Executable and not confirmed: show the warning, then call again with
 *  `confirmedExecutable: true`. Nothing was written or opened.
 */
{ kind: "needsConfirmation" };

/**  "Open .eml file…": the user cancelled the dialog, or the file opened in its own window. */
export type OpenEmlFileResult = { kind: "cancelled" } | { kind: "opened"; file: EmlFile };

/**  A dismissable suggestion, never a claim: "maybe still open". */
export type OpenReplyHint = {
	messageId: MessageId,
	accountId: AccountId,
	kind: OpenReplyKind,
	subject: string,
	/**  Awaiting: the first recipient; unanswered: the sender. */
	counterpart: Address | null,
	/**  Unix seconds. */
	date: number,
	/**  Whole days since `date`. */
	days: number,
};

/**  Why an open-reply hint is shown. */
export type OpenReplyKind = 
/**  The user asked a question and no answer came for some days. */
"awaiting_reply" | 
/**  Someone asked the user directly and the user has not answered. */
"unanswered_question";

/**  Settings of the open-reply hints (no AI involved). */
export type OpenReplySettings = {
	enabled: boolean,
	/**  A sent question counts as unanswered after this many days (1..=30). */
	days: number,
};

/**  Id of one operation (`operation.id`). Never reused; also the order of execution. */
export type OperationId = number;

/**  One operation as the activity view shows it. */
export type OperationInfo = {
	id: OperationId,
	batch: BatchId,
	accountId: AccountId,
	action: ActionKind,
	kind: OperationKind,
	state: OperationState,
	/**
	 *  Source mailbox and message; null for `create_mailbox`, or when they were deleted
	 *  locally since.
	 */
	mailboxId: MailboxId | null,
	messageId: MessageId | null,
	/**  Target of a move. */
	targetMailboxId: MailboxId | null,
	/**  Times the command was sent. */
	attempts: number,
	/**  Why it failed (`failed`), or the last transient error. */
	error: IpcError | null,
	conflict: ConflictReason | null,
	notice: OperationNotice | null,
	/**  Unix milliseconds. */
	createdAt: number,
	updatedAt: number,
};

/**  What an operation does on the server. */
export type OperationKind = "set_flag" | "move" | "expunge" | "create_mailbox" | 
/**  Stage 5: SMTP submission of a message (decision 0018). */
"send" | 
/**  Stage 5: APPEND of a draft version or of the copy of a sent message. */
"append" | 
/**  Stage 5: removal of an own copy (an old draft version), checked by Message-ID. */
"remove_copy" | 
/**  Audit 24.11.2026: RENAME of a folder of the user's own (JMAP: not supported yet). */
"rename_mailbox" | 
/**  Audit 24.11.2026: DELETE of a folder of the user's own, with its messages. */
"delete_mailbox";

/**  Something the user should know about a confirmed operation. */
export type OperationNotice = 
/**
 *  The server has no UIDPLUS and other messages in the source mailbox were marked deleted,
 *  so a plain EXPUNGE would have removed them too. The message was copied but its original
 *  stays in the source, marked deleted, until the mailbox is expunged.
 */
"left_marked_deleted" | 
/**
 *  Stage 5: the message was sent, but no copy went into Sent: the account has no Sent
 *  folder (the user can choose one with `setMailboxRole`).
 */
"no_sent_copy";

/**
 *  Where an operation stands.
 * 
 *  `queued` → `in_flight` (the command is about to be sent) → `confirmed` | `failed` |
 *  `conflict`. After a crash or a lost connection, `in_flight` operations are checked against
 *  the server before anything is repeated.
 */
export type OperationState = 
/**  Recorded, local change applied, waiting for the server. */
"queued" | 
/**  Sent or about to be sent; the outcome is not known yet. */
"in_flight" | 
/**  The server did it. */
"confirmed" | 
/**
 *  The server refused or the outbox gave up; the local change was reverted. The user can
 *  retry or discard it.
 */
"failed" | 
/**
 *  The server state changed meanwhile (the message was moved, deleted or modified
 *  elsewhere); the server wins and the user is told ([`ConflictReason`]).
 */
"conflict";

/**
 *  How many operations of an account wait for the server or need the user (status badge,
 *  activity view). Confirmed ones are not counted.
 */
export type OutboxCounts = {
	accountId: AccountId,
	/**  `queued` or `in_flight`. */
	pending: number,
	/**  `failed`: refused or given up, local change reverted. Retry or discard. */
	failed: number,
	/**  `conflict`: changed elsewhere meanwhile, the server's state was kept. Discard. */
	conflict: number,
};

/**  A message on its way, for the outbox view. */
export type OutgoingMail = {
	operationId: OperationId,
	accountId: AccountId,
	/**  The frozen draft while it exists (until the server accepted the message). */
	draftId: DraftId | null,
	subject: string,
	/**  The first recipients (at most five) and how many there are in all. */
	to: Address[],
	recipientCount: number,
	state: SendState,
	/**
	 *  When the submission starts (Unix ms): the end of the undo delay, or the time the user
	 *  chose (`scheduled`).
	 */
	sendAt: number,
	/**
	 *  Stage 10: the user chose the time ("send later"); otherwise `sendAt` is the end of the
	 *  undo delay.
	 */
	scheduled: boolean,
	/**  Why it failed, is unclear or waits (the last temporary error). */
	error: IpcError | null,
	/**  Times the submission was started. */
	attempts: number,
	/**  `noSentCopy` when no copy went into Sent (no Sent folder). */
	notice: OperationNotice | null,
	/**  Stage 16: "Senden und archivieren" was asked for; null otherwise. */
	archive: ArchiveAfterSend | null,
	/**
	 *  Stage 16: this is a read receipt (RFC 8098) the user chose to send, not a message of a
	 *  draft (`draftId` names no draft; there is nothing to edit).
	 */
	readReceipt: boolean,
	createdAt: number,
	updatedAt: number,
};

/**  `PARTSTAT` of an attendee. */
export type ParticipationStatus = "needs_action" | "accepted" | "declined" | "tentative" | "delegated";

/**  A row of "Pinned attachments": the attachment as it was pinned, and its message. */
export type PinnedAttachment = {
	/**  The message, as a list row (in its inbox where it lies there). */
	message: MessageListItem,
	/**  The attachment's position in the message (`AttachmentInfo.index`). */
	index: number,
	/**  Sanitised file name at pinning time. */
	name: string,
	mimeType: string,
	size: number,
	/**  What its preview shows; null when there is none. */
	preview: PreviewKind | null,
	/**  Unix milliseconds. */
	pinnedAt: number,
};

/**  Operating system the app runs on. */
export type Platform = "macos" | "windows" | "linux";

/**
 *  The user's shortcut changes for both platforms: a synced setting carries both, and each
 *  device uses the list of its own system.
 */
export type PlatformShortcuts = {
	macos: ShortcutOverride[],
	windows: ShortcutOverride[],
};

/**  User preferences stored in the `setting` table. */
export type Preferences = {
	theme: ThemePreference,
	language: LanguagePreference,
};

/**  How far back bodies are prefetched (Inbox, Sent, Drafts and flagged mail). */
export type PrefetchPeriod = "days7" | "days30" | "days90" | "days365" | "all";

/**  Prefetch settings (device class: disk space and connection differ per device; not synced). */
export type PrefetchSettings = {
	period: PrefetchPeriod,
	/**
	 *  Messages up to this RFC822.SIZE (bytes) are prefetched whole; larger ones only with
	 *  their text parts, so they can still be read offline. 0 prefetches text only.
	 */
	maxMessageSize: number,
};

export type PrefetchState = 
/**  Everything in the period is stored. */
"idle" | "running" | 
/**  The account is offline; continues when it reconnects. */
"paused";

/**  Progress of the prefetch of one account (event `prefetchProgress`). */
export type PrefetchStatus = {
	state: PrefetchState,
	/**  Bodies stored in the current run, and the run's total. */
	done: number,
	total: number,
	/**  Bytes fetched in the current run (below 2^53). */
	bytes: number,
};

/**  What the preview of an attachment shows. Null on an attachment the core does not preview. */
export type PreviewKind = 
/**  PNG, JPEG, GIF (first frame) or WebP, recognised by its bytes. */
"image" | 
/**  A PDF document, page by page. */
"pdf" | 
/**  Plain text (`text/plain`, CSV, Markdown, logs; never HTML or XML-based images). */
"text";

/**
 *  How the app talks to an account's server (stage 14, block D, decision 0041). Fixed when the
 *  account is set up.
 */
export type Protocol = 
/**  IMAP for reading, SMTP for sending: the account's `imap` and `smtp` servers. */
"imap" | 
/**
 *  JMAP (RFC 8620, RFC 8621) over HTTPS for reading, changes and sending: the account's
 *  `imap` server settings name the JMAP server (host, port, user name; always TLS), whose
 *  session resource is `https://<host>[:<port>]/.well-known/jmap`. `smtp` holds the same
 *  server and is not used.
 */
"jmap";

/**
 *  Provider-specific advice for the setup form. The UI shows one note per hint; the server
 *  settings are filled in either way.
 */
export type ProviderHint = 
/**  Needs an app password (Google account with 2-step verification). */
"gmail" | 
/**  Needs an app-specific password (Apple ID). */
"icloud" | 
/**  Needs an app password (Yahoo account security settings). */
"yahoo" | 
/**  Needs an app password (Fastmail settings, Privacy & Security). */
"fastmail" | 
/**
 *  Outlook.com, Hotmail, Live: Microsoft only accepts OAuth sign-in, which the app supports
 *  from stage 14. A password login is expected to fail.
 */
"outlook" | 
/**
 *  Proton Mail works only through Proton Mail Bridge on this computer (paid plan): use the
 *  user name and password that Bridge shows, and trust Bridge's certificate in the system.
 */
"proton" | 
/**  GMX: IMAP access must be turned on first (web mail settings, POP3/IMAP). */
"gmx" | 
/**  WEB.DE: IMAP access must be turned on first (web mail settings, POP3/IMAP). */
"webde" | 
/**
 *  Telekom (t-online.de, magenta.de): needs the separate email password from the Telekom
 *  customer center, not the Telekom login password.
 */
"tonline";

/**
 *  Quiet hours: no sound and no banner between `start` and `end` (minutes after local
 *  midnight; may wrap midnight). Notifications are dropped, not delayed.
 */
export type QuietHours = {
	enabled: boolean,
	startMinute: number,
	endMinute: number,
};

/**
 *  Language of the attribution line ("On … wrote:") and the forward header of a new reply or
 *  forward: the UI's resolved language.
 */
export type QuoteLanguage = "en" | "de";

/**  Where the answer goes relative to the quoted original. */
export type QuotePosition = 
/**  Answer and signature above the quote (the common default). */
"above" | 
/**  The quote first, then the answer and the signature. */
"below";

/**  Where the user's answer to a read-receipt request stands. */
export type ReadReceiptAnswer = 
/**  Not answered: the reading pane may ask (send or decline). */
"ask" | 
/**  The receipt is in the outbox (see the outbox view for its state). */
"queued" | 
/**  The server accepted the receipt. */
"sent" | 
/**  The user declined; nothing is sent. */
"declined" | 
/**
 *  Answered elsewhere: the message carries the `$MDNSent` keyword (RFC 3503) another
 *  program or device set. Nothing is offered.
 */
"answered_elsewhere" | 
/**  Read receipts are set to `never`: nothing is offered. */
"off";

/**
 *  Read receipts of one message (`getReadReceipt`): an incoming request and the receipts that
 *  came back for it. Read from the stored message; empty while its body is not stored.
 */
export type ReadReceiptInfo = {
	/**
	 *  The message asks for a read receipt; null otherwise (also for the user's own mail and
	 *  for read receipts themselves).
	 */
	request: ReadReceiptRequest | null,
	/**  The message (one the user sent) asked for a read receipt. */
	requested: boolean,
	/**  Receipts that came back for this message, newest first. */
	received: ReceivedReadReceipt[],
	/**  The message is itself a read receipt (for the message with this Message-ID). */
	receiptFor: string | null,
};

/**
 *  How the app answers read-receipt requests of incoming mail. It never sends one by itself:
 *  with `ask` the reading pane offers to send one (`sendReadReceipt`) or to decline; with
 *  `never` it offers nothing and `sendReadReceipt` is refused.
 */
export type ReadReceiptPolicy = "ask" | "never";

/**  An incoming message asks for a read receipt. */
export type ReadReceiptRequest = {
	/**  Where the receipt would go (`Disposition-Notification-To`). */
	to: string,
	/**
	 *  That address is not the message's `Return-Path` (or there is none): RFC 8098 asks to
	 *  confirm with the user, the UI says so in its question.
	 */
	returnPathDiffers: boolean,
	answer: ReadReceiptAnswer,
};

/**  Where a window shows the opened message. */
export type ReadingPanePosition = 
/**  Right of the list (the default). */
"right" | 
/**  Below the list. */
"bottom" | 
/**  In place of the list. */
"replace";

/**
 *  Reading preferences stored in the `setting` table (stage 4). Separate from [`Preferences`],
 *  so the appearance settings keep their shape.
 */
export type ReadingPreferences = {
	markReadOnOpen: MarkReadOnOpen,
};

/**
 *  What the recipient's program reported in a read receipt (`Disposition` field, RFC 8098
 *  3.2.6).
 */
export type ReceiptDisposition = 
/**  Shown to the recipient (not proof that it was read). */
"displayed" | 
/**  Deleted without being shown. */
"deleted" | 
/**  Sent somewhere else (printed, faxed, forwarded) without being shown. */
"dispatched" | 
/**  Processed by a program without being shown. */
"processed" | 
/**  Anything else. */
"other";

/**  A read receipt that came back for a message the user sent. */
export type ReceivedReadReceipt = {
	/**  The recipient it reports on (`Final-Recipient`), if given. */
	recipient: string | null,
	disposition: ReceiptDisposition,
	/**  When the receipt arrived (its sort date), Unix milliseconds. */
	receivedAt: number,
};

/**  A search of this device's history. */
export type RecentSearch = {
	query: string,
	/**  Unix milliseconds of the last use. */
	usedAt: number,
};

/**  `FREQ` of a recurrence rule. */
export type RecurrenceFrequency = "daily" | "weekly" | "monthly" | "yearly" | 
/**  `SECONDLY`, `MINUTELY` or `HOURLY`: shown from `rule`. */
"other";

/**  Scope of `loadRemoteContent`. */
export type RemoteContentScope = 
/**  This rendering only; nothing is stored. */
"once" | 
/**  Always for this sender address in this account (stored, synced in stage 11). */
"sender";

/**
 *  Opaque id of one rendering of a body: 32 lowercase hex digits (128 random bits), made by the
 *  core. Link placeholders of that rendering carry it (`https://link.invalid/<token>/<index>`);
 *  the real targets stay in the core under it. Unguessable, so a mail cannot point at the links
 *  of another rendering.
 */
export type RenderToken = string;

/**  Why a mailbox has its role. */
export type RoleSource = 
/**  The server said so: a SPECIAL-USE attribute (RFC 6154), or the name `INBOX`. */
"server" | 
/**  Guessed from the folder name (English and German names, Gmail folders). */
"heuristic" | 
/**  Set by the user; survives every refresh of the folder list. */
"user" | 
/**  No role (`custom`) and no reason to think otherwise. */
"none";

/**
 *  An action of a local rule. Moving and marking as read are writing actions: they go through
 *  the outbox and are skipped (and reported) on read-only accounts.
 */
export type RuleAction = 
/**  To a mailbox of the message's account, by decoded path (stable across devices). */
{ type: "move"; accountId: AccountId; path: string } | { type: "markRead" } | 
/**  Sets the message's category (this message only; "always as …" is a sender rule). */
{ type: "setCategory"; category: MessageCategory } | { type: "pin" } | 
/**  Notify about the message, or not, whatever the notification settings say. */
{ type: "notify"; enabled: boolean };

/**  A condition of a local rule. */
export type RuleCondition = 
/**  The From address or name. */
{ field: "from"; op: TextMatchOp; value: string } | 
/**  Any To or Cc address or name. */
{ field: "to"; op: TextMatchOp; value: string } | { field: "subject"; op: TextMatchOp; value: string } | 
/**  The `List-Id` identifier (`contains` or `is`). */
{ field: "list"; op: TextMatchOp; value: string } | 
/**  The message arrived in this account. */
{ field: "account"; accountId: AccountId };

/**  Stable id of a local rule (UUID v4, lower case), synced like the rule. */
export type RuleId = string;

/**  What the UI sends to create or change a local rule. */
export type RuleInput = {
	name: string,
	enabled: boolean,
	matchAll: boolean,
	conditions: RuleCondition[],
	actions: RuleAction[],
	stop: boolean,
};

/**  Why a rule's action did not run. */
export type RuleSkipReason = 
/**  The account is read-only; moving and marking need writing. */
"read_only" | 
/**  The target mailbox does not exist (any more) or belongs to another account. */
"missing_mailbox" | 
/**  The message has no Message-ID, so it cannot be pinned. */
"no_message_id" | 
/**  The outbox refused the action (detail in the log). */
"failed";

/**  What sanitising removed or simplified, for a hint below the editor. */
export type SanitizeReport = {
	/**  Images dropped (not one of the signature's own `cid:` images: external, `data:`, SVG). */
	imagesRemoved: number,
	/**  Colours, fonts, sizes, alignment, tables or headings were simplified. */
	formattingSimplified: boolean,
};

/**  `saveAllAttachments`: where the attachments went, or nothing when the dialog was cancelled. */
export type SaveAllAttachmentsResult = { kind: "saved"; 
/**  The folder the user chose. */
folder: string; 
/**  Files written. */
saved: number; 
/**  Of those, written under another name because the name was taken. */
renamed: number } | { kind: "cancelled" };

/**  Result of `saveAttachment`. */
export type SaveAttachmentResult = 
/**  Written to the path the user chose in the system dialog. */
{ kind: "saved"; path: string } | 
/**  The user closed the dialog. */
{ kind: "cancelled" };

/**  A saved search, as the sidebar shows it. */
export type SavedSearch = {
	id: SavedSearchId,
	name: string,
	/**  The search as the user typed it. */
	query: string,
	/**  Order in the sidebar; new ones come last. */
	position: number,
	/**  Unix milliseconds. */
	updatedAt: number,
};

/**  Id of a saved search: a UUID, the same on every device (the sync record id). */
export type SavedSearchId = string;

/**  A saved signature and what sanitising changed. */
export type SavedSignature = {
	signature: SignatureInfo,
	notes: SanitizeReport,
};

/**  A saved template and what sanitising changed. */
export type SavedTemplate = {
	template: TemplateInfo,
	notes: SanitizeReport,
};

/**
 *  Where the query's words occur in the fields the list shows. Computed from the stored text
 *  (the index holds no text, decision 0003); a match deep in the body has no range here.
 */
export type SearchHighlights = {
	subject: TextRange[],
	/**  In the sender's display name, or in the address when there is no name. */
	from: TextRange[],
	preview: TextRange[],
};

/**
 *  One result: the message as a list row (one of its locations), every mailbox it lies in, and
 *  the highlighted ranges.
 */
export type SearchHit = {
	message: MessageListItem,
	/**  All locations, ascending; `message.mailboxId` is one of them. */
	mailboxIds: MailboxId[],
	highlights: SearchHighlights,
	/**
	 *  The whole message is stored locally, so its text was searched. Otherwise only headers
	 *  (and the text parts of a large message) were: "search on the server" can find more.
	 */
	bodyLocal: boolean,
	/**
	 *  Decision 0039: the message's conversation (null while it is not threaded) and how many
	 *  messages it has, so the results can show one row per conversation.
	 */
	threadId: number | null,
	threadMessageCount: number,
};

/**  State of the full-text index. */
export type SearchIndexState = 
/**  Every stored message is indexed. */
"ready" | 
/**
 *  Existing messages are being indexed (after the update to stage 7); results may be
 *  missing older messages until it is done.
 */
"building" | 
/**  A new index is being built in the background; searches use the old one meanwhile. */
"rebuilding";

export type SearchIndexStatus = {
	state: SearchIndexState,
	/**  0..=100, by message dates (the index is built from old to new). */
	percent: number,
};

/**  One page of results, newest first. */
export type SearchPage = {
	hits: SearchHit[],
	/**  Null on the last page. A page can be shorter than the limit and still have a next one. */
	nextCursor: ListCursor | null,
	/**  Parser errors, contradictions and unknown accounts or mailboxes, sorted by position. */
	problems: SearchProblem[],
	/**  Every term of the query, for chips. */
	terms: SearchTermInfo[],
	/**
	 *  The query cannot match anything (a contradiction, an unknown account or mailbox, an
	 *  empty date range); `hits` is empty.
	 */
	matchesNothing: boolean,
	index: SearchIndexStatus,
};

/**  A problem at a place in the query; the UI marks the range and shows a text for the code. */
export type SearchProblem = {
	code: SearchProblemCode,
	range: TextRange,
};

/**  What a problem in the query is. The parser's error kinds plus what only the engine knows. */
export type SearchProblemCode = "unclosed_quote" | "missing_value" | "unknown_filter" | "unknown_value" | "invalid_date" | "invalid_age" | "nothing_to_search" | "prefix_too_short" | "missing_term" | "misplaced_or" | "or_needs_text" | "or_with_exclusion" | "too_long" | "too_many_terms" | 
/**  The term contradicts another one (`is:unread is:read`); the query finds nothing. */
"conflict" | 
/**  `account:` names no account (address, name or id). */
"unknown_account" | 
/**  `in:` names no mailbox of the accounts searched. */
"unknown_mailbox" | 
/**
 *  The server cannot search for this term (`has:attachment`, `is:snoozed`); it is applied
 *  to the local data of the results only (server search).
 */
"not_on_server";

/**  One search call. */
export type SearchRequest = {
	/**  As typed, at most 2048 bytes are read. */
	query: string,
	scope: SearchScope,
	/**  `nextCursor` of the previous page; null for the first page. */
	cursor: ListCursor | null,
	/**  1..=200. */
	limit: number,
	/**
	 *  Search as you type: the word the input ends in matches as a prefix (`rech` finds
	 *  "Rechnung"). Off for a submitted search.
	 */
	typing: boolean,
	/**
	 *  The user's region writes `01/02/2026` month first (United States). Dates with dots,
	 *  ISO dates and month names do not depend on it.
	 */
	monthFirst?: boolean,
};

/**
 *  Where a search looks. Hidden accounts are left out of `all` and `group` (as from the
 *  unified inbox); searching one account or mailbox explicitly always works.
 */
export type SearchScope = 
/**  Every visible account. */
{ kind: "all" } | { kind: "account"; accountId: AccountId } | { kind: "mailbox"; mailboxId: MailboxId } | 
/**  The visible accounts of a group. */
{ kind: "group"; groupId: AccountGroupId };

/**
 *  One term as typed, for a chip: kind, whether it was excluded with `-`, the whole term and
 *  its value (without key and quotes).
 */
export type SearchTermInfo = {
	kind: SearchTermKind,
	negated: boolean,
	range: TextRange,
	valueRange: TextRange,
	/**  Part of an `OR` group (`a OR b`). */
	alternative: boolean,
};

/**  What a term of the query is, for chips. */
export type SearchTermKind = "text" | "from" | "to" | "cc" | "subject" | "filename" | "in" | "account" | "has_attachment" | "is_unread" | "is_read" | "is_flagged" | "is_snoozed" | "before" | "after" | "older_than" | "newer_than";

/**
 *  Transport security of a server connection. There is deliberately no plaintext option: a
 *  password never travels unencrypted, and the test server offers TLS and STARTTLS as well.
 */
export type Security = 
/**  TLS from the first byte (IMAP 993, SMTP 465). */
"tls" | 
/**
 *  Plain connect, then `STARTTLS` before anything else (IMAP 143, SMTP 587). If the server
 *  does not offer STARTTLS, the connection fails; it never continues unencrypted.
 */
"starttls";

/**  Stage 10: a time chosen for "send later". */
export type SendLater = {
	/**  Unix milliseconds; in the future, at most a year ahead. */
	sendAt: number,
};

/**  Where a sent message stands, for the outbox view ("Ausgang"). */
export type SendState = 
/**
 *  Waiting until `sendAt`: the undo delay, or (`scheduled`) the time the user chose
 *  ("send later", stage 10). Can be cancelled (back to the draft) or, when scheduled,
 *  moved (`rescheduleSend`). It is sent only if the app runs and is online at that time.
 */
"scheduled" | 
/**  Due, waiting for the server (offline, or a temporary refusal); `error` says why. */
"queued" | 
/**  Being submitted right now; can no longer be cancelled. */
"sending" | 
/**
 *  The connection broke after the whole message went out: the core looks for it in the
 *  Sent folder (only where the server files sent mail itself).
 */
"verifying" | 
/**
 *  It stayed unclear whether the message went out. The user decides
 *  ([`UnclearDecision`]); nothing is sent again by itself.
 */
"unclear" | 
/**  Refused (`error`); nothing was delivered. Retry, or edit the draft again. */
"failed" | 
/**
 *  Stage 10: scheduled for a time when the app was not running, and more than an hour has
 *  passed (`error.code: send_missed`). Nothing was sent; the user decides
 *  ([`MissedSendDecision`]).
 */
"missed" | 
/**  The server accepted it. */
"sent";

/**  A sender chip on a bundle row. */
export type SenderChip = {
	/**  The address as first seen (newest message), with the first display name seen. */
	sender: Address,
	count: number,
	unread: number,
};

/**
 *  A sender, domain or list a user rule applies to. `value` as the user chose it; the
 *  classifier normalises it (lower case, ASCII domain) before comparing.
 */
export type SenderKey = {
	kind: SenderKeyKind,
	value: string,
};

/**  What a correction or an important mark applies to. */
export type SenderKeyKind = 
/**  One sender address. */
"address" | 
/**  A domain and all its subdomains. */
"domain" | 
/**  A mailing list, by the identifier of its `List-Id`. */
"list_id";

/**
 *  A rule for a sender, domain or list: the category correction ("always as …") and the
 *  important mark. Synced (class sync).
 */
export type SenderRule = {
	/**  UUID, lower case. */
	id: string,
	/**  The key as normalised for comparing (lower case, ASCII domain). */
	key: SenderKey,
	/**  The correction; null if the rule only marks the sender important. */
	category: MessageCategory | null,
	important: boolean,
	/**  Unix milliseconds. */
	updatedAt: number,
};

/**  Who puts the copy of a sent message into the Sent folder. */
export type SentCopyMode = 
/**  Recognised from the server: Gmail files sent mail itself, everyone else needs the app. */
"auto" | 
/**  The app appends the copy. */
"app" | 
/**  The server files it itself; the app appends nothing. */
"server";

/**
 *  Result of searching on the server (IMAP SEARCH over the read-only connection) for messages
 *  whose content is not stored locally.
 */
export type ServerSearchResult = {
	/**
	 *  Messages the server found whose whole body is not stored locally, newest first, at most
	 *  the request's limit. Every hit is a stored message (headers are always local).
	 */
	hits: SearchHit[],
	/**  More hits than returned. */
	truncated: boolean,
	/**  Mailboxes searched. */
	searched: MailboxId[],
	/**  Mailboxes whose search failed (offline, refused); the rest still counts. */
	failed: MailboxId[],
	/**  Server hits not stored locally yet (first sync still running). */
	notSynced: number,
	/**  Problems of the query, including terms the server cannot search (`notOnServer`). */
	problems: SearchProblem[],
};

/**  Where and how to reach one server (IMAP or SMTP). No password: that lives in the keychain. */
export type ServerSettings = {
	host: string,
	port: number,
	security: Security,
	username: string,
};

/**
 *  Why a server the online search found deserves a second look (security review N-4,
 *  RFC 6186 section 6): DNS and autoconfig answers are not verified, so a network attacker
 *  during setup could propose his own server.
 */
export type ServerWarning = 
/**
 *  The host is neither the address's domain nor one of its subdomains (and not a server of
 *  the built-in provider table).
 */
"outsideDomain" | 
/**  The host is an IP address (IPv4 or IPv6), not a name. */
"ipAddress";

/**
 *  At most one [`ServerWarning`] per server of a [`DiscoveryResult`]; an IP address is not
 *  also reported as outside the domain.
 */
export type ServerWarnings = {
	imap?: ServerWarning | null,
	smtp?: ServerWarning | null,
	jmap?: ServerWarning | null,
};

/**  The preview a new device shows before it merges (`previewSettingsSyncJoin`). */
export type SettingsSyncPreview = {
	kinds: SyncKindCount[],
	/**  Addresses of accounts that will be added; each asks for its password afterwards. */
	newAccounts: string[],
	/**  Records of this device that will be uploaded. */
	uploads: number,
	/**  Devices that already take part. */
	devices: SyncDevice[],
};

/**  Overall state of the settings sync on this device. */
export type SettingsSyncState = 
/**  Not turned on. `detectedAccounts` lists accounts whose mailbox holds a sync folder. */
"off" | 
/**  On, the last pass worked (or none ran yet). */
"active" | 
/**
 *  The sync key is missing from the keychain (`sync_key_missing`), or the folder was reset
 *  on another device (`sync_key_changed`): enter the passphrase again
 *  (`previewSettingsSyncJoin`, then `joinSettingsSync`). Nothing is written.
 */
"needsPassphrase" | 
/**
 *  On, but the last pass failed (`lastError`); retried with the account's sync. Reading
 *  and sending mail are not affected.
 */
"error";

/**  Everything the settings page shows about the sync. */
export type SettingsSyncStatus = {
	state: SettingsSyncState,
	/**  The sync account; null while off. */
	accountId: AccountId | null,
	/**  Wire name of the sync folder; null while off. */
	folder: string | null,
	/**  Unix ms of the last complete pass; null before the first. */
	lastSyncAt: number | null,
	/**  Why the last pass failed (`error`, `needsPassphrase`). */
	lastError: IpcError | null,
	/**  Local changes not yet in the folder. */
	pendingChanges: number,
	/**
	 *  Entries of the folder the last pass left out and reported (modified, damaged, from
	 *  another key, too large, or waiting for the next pass); the rest synced as usual.
	 */
	rejectedEntries: number,
	devices: SyncDevice[],
	questions: SyncQuestion[],
	/**
	 *  Accounts taken over from another device that still need their password on this one
	 *  (`updatePassword`).
	 */
	accountsNeedingPassword: AccountId[],
	/**
	 *  Accounts whose mailbox holds a sync folder while the sync is off here: offer to join
	 *  with the passphrase.
	 */
	detectedAccounts: AccountId[],
	/**
	 *  Server settings another device changed for an account of this device. Not applied:
	 *  the account keeps its servers (and the password stays with them) until the user
	 *  confirms or dismisses the change (`resolveServerChange`, decision 0040).
	 */
	serverChanges: SyncServerChange[],
};

/**
 *  One key combination. `mod` is Cmd on macOS and Ctrl on Windows; Option/Alt combinations do
 *  not exist (`docs/ARCHITECTURE.md`, "Keyboard shortcuts").
 */
export type Shortcut = {
	/**  The character the key produces (`event.key`), 1 to 20 characters. */
	key: string,
	shift: boolean,
	mod: boolean,
};

/**
 *  The complete list of shortcuts the user gave one command (an empty list: the command has no
 *  shortcut). Commands without an entry keep the defaults of the action directory, which only
 *  the UI knows.
 */
export type ShortcutOverride = {
	/**  Command id of the action directory: 1 to 64 ASCII letters, digits, `.`, `_`, `-`, `:`. */
	command: string,
	shortcuts: Shortcut[],
};

/**
 *  Id of a signature: a UUID, the same on every device (the sync record id). A signature
 *  taken over from a stage 5 text signature has the UUID of its identity.
 */
export type SignatureId = string;

/**
 *  One image of a signature as a `data:` URL, for the signature editor (the editor shows it in
 *  place of `cid:<contentId>` and writes `cid:<contentId>` back when saving).
 */
export type SignatureImageData = {
	contentId: string,
	dataUrl: string,
};

/**  An image a signature shows (`<img src="cid:CONTENT_ID">` in its HTML). */
export type SignatureImageInfo = {
	/**
	 *  The `Content-ID` of the image part, without angle brackets; the HTML refers to it as
	 *  `cid:<contentId>`.
	 */
	contentId: string,
	fileName: string,
	/**  `image/png`, `image/jpeg`, `image/gif` or `image/webp` (recognised from the bytes). */
	mime: string,
	size: number,
};

/**  A signature of the pool. */
export type SignatureInfo = {
	id: SignatureId,
	name: string,
	/**  Allowlisted editor HTML; images as `cid:` (see [`SignatureImageData`] for showing them). */
	html: string,
	/**  The plain text (without the `-- ` separator, added when the message is put together). */
	text: string,
	images: SignatureImageInfo[],
	/**  Unix milliseconds. */
	updatedAt: number,
};

/**
 *  A signature to create (`id` null) or change. The HTML is sanitised with the allowlist of
 *  outgoing mail; `cid:` images must name images of this signature.
 */
export type SignatureInput = {
	id: SignatureId | null,
	name: string,
	html: string,
};

/**
 *  When a snoozed message comes back. Times are computed in the user's time zone; daylight
 *  saving changes are taken into account (a local time that does not exist moves forward).
 */
export type SnoozeChoice = 
/**  Three hours from now, rounded up to the full hour; only while that is still today. */
{ kind: "laterToday" } | 
/**  Tomorrow at 08:00. */
{ kind: "tomorrow" } | 
/**  Next Saturday at 09:00 (on a weekend: the following one). */
{ kind: "weekend" } | 
/**  Next Monday at 08:00. */
{ kind: "nextWeek" } | 
/**  A time the user picked, Unix milliseconds; at least a minute ahead, at most 5 years. */
{ kind: "at"; at: number };

/**  A snooze on a list row. */
export type SnoozeMark = {
	/**  When the message comes (or came) back, Unix milliseconds. */
	until: number,
	/**  It came back and waits for the user (shown on top with a mark). */
	returned: boolean,
};

/**  What `snoozeMessages` answers. */
export type SnoozeResult = {
	/**  When the messages come back, Unix milliseconds. */
	until: number,
};

/**
 *  The times the snooze menu offers right now, Unix milliseconds. `laterToday` is null late in
 *  the day.
 */
export type SnoozeTimes = {
	laterToday: number | null,
	tomorrow: number,
	weekend: number,
	nextWeek: number,
};

/**  The platform a list of notification sounds is for. */
export type SoundPlatform = "macos" | "windows" | 
/**  Neither: the system's notification sound, no choice. */
"other";

/**
 *  What kept the local database from opening at start (`getStartupProblem`). The core runs on
 *  without it: every call that needs the database fails with `error` until the next start, and
 *  the app shell says what happened and what to do.
 */
export type StartupProblem = {
	error: IpcError,
	/**  The database file the app tried to open. */
	databasePath: string,
	/**  The folder with the copies the app takes before every update of the database. */
	backupDir: string,
	/**  Those copies, newest first (file names); empty if there are none. */
	backups: string[],
};

/**  A device that takes part (each one writes a small record). */
export type SyncDevice = {
	/**  Random id of the device in the sync (not tied to the hardware). */
	id: string,
	name: string,
	system: string,
	/**  Unix ms; updated at most once a day. */
	lastSeenAt: number,
	/**  This device. */
	current: boolean,
};

/**  What joining would take over, per kind of data. */
export type SyncKindCount = {
	/**  Kind name from `docs/SYNC.md` (`setting`, `signature`, `snooze`, …). */
	kind: string,
	/**  New here. */
	added: number,
	/**  Exists here and changes. */
	changed: number,
	/**  Exists here and is removed. */
	removed: number,
};

/**  Progress of the first sync of one mailbox. */
export type SyncProgress = {
	mailboxId: MailboxId,
	/**  Messages of this mailbox stored locally so far. */
	done: number,
	/**  Messages in this mailbox on the server (EXISTS when the pass started). */
	total: number,
};

/**  A decision only the user can make. */
export type SyncQuestion = 
/**
 *  Another device removed this account (or it vanished from the folder long ago). It stays
 *  here until the user decides (`resolveSyncQuestion`): remove it here too, or keep it,
 *  which brings it back on every device.
 */
{ type: "accountRemoved"; accountId: AccountId; email: string };

/**
 *  Server settings that arrived through the settings sync for an existing account and differ
 *  from the ones this device uses (finding F1, decision 0040). The account's own `imap`/`smtp`
 *  are the settings in use.
 */
export type SyncServerChange = {
	accountId: AccountId,
	imap: ServerSettings,
	smtp: ServerSettings,
};

/**  Which tasks the "Aufgaben" view lists. */
export type TaskFilter = "open" | "done" | "all";

/**  A task mark on a list row. */
export type TaskMark = {
	done: boolean,
};

/**  Something to point out after filling a template. */
export type TemplateFillProblem = 
/**  `{{name}}` is no known placeholder; it stays as written. */
{ kind: "unknown"; name: string } | 
/**  No value (for example a recipient without a name) and no fallback: left empty. */
{ kind: "missing"; placeholder: string };

/**  Id of a template: a UUID, the same on every device. */
export type TemplateId = string;

/**  A template. */
export type TemplateInfo = {
	id: TemplateId,
	name: string,
	/**  May hold placeholders such as `{{first_name}}`. */
	subject: string,
	/**  Allowlisted editor HTML with placeholders. */
	html: string,
	/**  Known placeholders the template uses (`first_name`, `date`, …) and unknown ones. */
	placeholders: string[],
	unknownPlaceholders: string[],
	/**
	 *  Stage 16: recipients the template prefills (empty for older templates). Each address
	 *  is in one field only; at most [`MAX_TEMPLATE_RECIPIENTS`] together.
	 */
	to: Address[],
	cc: Address[],
	bcc: Address[],
	updatedAt: number,
};

/**  A template to create (`id` null) or change. */
export type TemplateInput = {
	id: TemplateId | null,
	name: string,
	subject: string,
	html: string,
	/**
	 *  Stage 16: recipients to prefill; left out = none. Every address must be valid
	 *  (`invalid_address` otherwise); an address given twice is kept once, in the first field.
	 */
	to?: Address[],
	cc?: Address[],
	bcc?: Address[],
};

/**  How a text condition compares (case and accents ignored). */
export type TextMatchOp = "contains" | 
/**  The whole value (for addresses: the address). */
"is" | 
/**  Addresses: the domain or a subdomain of it. */
"domain";

/**  A range of UTF-16 code units (`start..end`). */
export type TextRange = {
	start: number,
	end: number,
};

/**  A piece of a text body. */
export type TextSegment = { kind: "text"; text: string } | 
/**  A URL or address found in the text; `index` for `describeLink`/`openLink`. */
{ kind: "link"; text: string; index: number };

export type ThemePreference = "system" | "light" | "dark";

/**  One message of an open thread. */
export type ThreadEntry = {
	/**  As a list row of one of its locations (the requested mailbox if it lies there). */
	message: MessageListItem,
	/**  All locations, ascending. */
	mailboxIds: MailboxId[],
};

/**
 *  One conversation in a list: the newest of its messages in the listed mailbox, how many it
 *  has (in all mailboxes of the account) and how many of those are unread.
 */
export type ThreadListItem = {
	/**  The newest message of the thread in this mailbox; the row shows it. */
	message: MessageListItem,
	/**
	 *  Local thread id; null while the message is not threaded yet (right after the update to
	 *  stage 7). Changes when threads merge: open a thread by `message.id` (`getThread`).
	 */
	threadId: number | null,
	messageCount: number,
	/**  Messages of the thread unread in at least one mailbox. */
	unreadCount: number,
	/**
	 *  Sort date of the thread's newest message anywhere (Unix milliseconds), for example a
	 *  reply in Sent.
	 */
	lastActivity: number,
	/**
	 *  Decision 0039: the distinct senders of the conversation, oldest first, at most
	 *  [`MAX_CONVERSATION_PARTICIPANTS`] (compared by address without case). Like the two
	 *  marks below, taken from the newest 200 messages of the conversation (the counts are
	 *  exact).
	 */
	participants: Address[],
	/**  Decision 0039: a message of the conversation has attachments. */
	hasAttachments: boolean,
	/**  Decision 0039: a message of the conversation is flagged (in any mailbox). */
	flagged: boolean,
};

export type ThreadPage = {
	items: ThreadListItem[],
	/**  Null on the last page. */
	nextCursor: ListCursor | null,
};

/**  Every message of a thread over all mailboxes of its account, oldest first. */
export type ThreadView = {
	threadId: number | null,
	messages: ThreadEntry[],
	/**
	 *  Messages in the thread; more than `messages.length` if the thread was cut to the newest
	 *  [`MAX_THREAD_MESSAGES`].
	 */
	total: number,
};

/**  Copy or move to a mailbox of another account. */
export type TransferMode = 
/**  The original stays. */
"copy" | 
/**  The original is removed from the source once the copy is confirmed in the target. */
"move";

/**
 *  The UI settings of `getUiPreferences` / `setUiPreferences`. Shortcuts, text size, (stage
 *  16) the accent theme, (decision 0039) the conversation view and (stage 17) the column's views
 *  are synchronised between devices; the recent commands and the AI panel's state stay on this
 *  device.
 */
export type UiPreferences = {
	shortcuts: PlatformShortcuts,
	/**  Percent of the system's text size, 80 to 150. */
	textSize: number,
	/**  Keys of the palette entries used last, newest first, at most 5, no duplicates. */
	recentCommands: string[],
	/**  The AI panel unfolded (default) or folded in; device only (decision 0028). */
	aiPanel: AiPanelState,
	/**
	 *  Stage 16 (decision 0036): the accent colours; synced like the text size. Only the six
	 *  themes are accepted (anything else is refused when the value is read from the UI).
	 */
	accentTheme: AccentTheme,
	/**
	 *  Decision 0039: lists show one row per conversation (default) instead of one per message;
	 *  synced like the text size.
	 */
	conversations: boolean,
	/**
	 *  Stage 17: the views of the column's "Views" section and of the rail, in the user's order,
	 *  each shown or hidden; synced like the text size. Empty is the default: every view in the
	 *  UI's order. A view the list does not name (one added by a later version) keeps its default
	 *  place and visibility. At most 32 entries, no id twice.
	 */
	columnViews: ColumnView[],
};

/**  The user's answer to an unclear send. */
export type UnclearDecision = 
/**  It arrived (the user checked): finish as sent (copy into Sent, draft removed). */
"treat_as_sent" | 
/**
 *  Submit it once more with the same Message-ID. The user confirmed that recipients may get
 *  it twice.
 */
"send_again";

/**  Which inboxes a unified view mixes. */
export type UnifiedView = 
/**  The inboxes of every visible account. */
{ kind: "all" } | 
/**  The inboxes of the group's visible accounts. */
{ kind: "group"; groupId: AccountGroupId };

/**  Where an "unread first" list continues. */
export type UnreadFirstCursor = {
	phase: UnreadPhase,
	/**  Within the phase: messages with a smaller id. Null: the phase starts from the top. */
	before: ListCursor | null,
};

/**
 *  One page of an "unread first" list: the unread rows come before the read ones (each row's
 *  `unread` tells where the group ends).
 */
export type UnreadFirstPage = {
	items: MessageListItem[],
	/**  Null on the last page. */
	nextCursor: UnreadFirstCursor | null,
};

/**
 *  Decision 0039: "unread first" as conversations: the conversations with an unread message in
 *  the listed mailboxes, then the others.
 */
export type UnreadFirstThreadPage = {
	items: ThreadListItem[],
	/**  Null on the last page. */
	nextCursor: UnreadFirstCursor | null,
};

/**  Which part of an "unread first" list a page or cursor is in. */
export type UnreadPhase = 
/**  The unread messages, newest first. */
"unread" | 
/**  Then the read ones, newest first. */
"read";

/**  How the user chose to unsubscribe. */
export type UnsubscribeMethod = "oneClick" | "mailto" | "web";

/**
 *  What a message offers for unsubscribing, from `List-Unsubscribe` and
 *  `List-Unsubscribe-Post`.
 */
export type UnsubscribeOptions = {
	/**  One-click (RFC 8058): an HTTPS POST the core sends after the click. Shows the host. */
	oneClickHost: string | null,
	/**  A `mailto:` address: a prepared draft the user sends. */
	mailto: string | null,
	/**  An `http`/`https` page that only opens in the browser, after the user confirmed. */
	web: string | null,
};

/**  The result of an unsubscribe click. */
export type UnsubscribeOutcome = 
/**  The list's server accepted the one-click request (HTTP 2xx). */
{ kind: "requested"; status: number } | 
/**  Open the composer with these fields; the user sends the request. */
{ kind: "compose"; request: ComposeRequest } | 
/**  The page was handed to the system browser. */
{ kind: "opened" };

/**  `getUpdateInfo` and the update commands: the setting, whether to ask, and the state. */
export type UpdateInfo = {
	/**  The running version. */
	currentVersion: string,
	/**
	 *  This build can check for and install updates (false in development builds and builds
	 *  without the updater, where the About page only shows the version).
	 */
	supported: boolean,
	autoCheck: boolean,
	/**  Show the one-time question now: not answered yet, and at least one account is set up. */
	askConsent: boolean,
	/**  Unix ms of the last check, if any. */
	lastCheckMs: number | null,
	status: UpdateStatus,
};

/**  Where the update is. Only ever changes on the core's side; the UI shows it. */
export type UpdateStatus = 
/**  No check since the app started. */
{ state: "idle" } | 
/**  A check is running. */
{ state: "checking" } | 
/**  The last check found no newer version. */
{ state: "upToDate"; checkedAtMs: number } | 
/**  A newer version is published; nothing was downloaded yet. */
{ state: "available"; update: AvailableUpdate } | 
/**  The download runs; `total` is unknown if the server does not say. */
{ state: "downloading"; version: string; downloaded: number; total: number | null } | 
/**  Downloaded and its signature checked; installs with the user's "Restart to install". */
{ state: "ready"; version: string } | 
/**  Installing; the app restarts (macOS) or the installer takes over (Windows). */
{ state: "installing"; version: string } | 
/**  The last step failed. `version` is the update it concerned, if one was found. */
{ state: "failed"; version: string | null; error: IpcError };

/**
 *  The layout of one window, stored per window on this device (not synchronised: the screens
 *  differ). `getWindowLayout` / `setWindowLayout` take the window from the calling window.
 */
export type WindowLayout = {
	readingPane: ReadingPanePosition,
	density: Density,
	/**  The accounts-and-folders column is shown (default) instead of the icon rail alone. */
	sidebarExpanded: boolean,
	/**
	 *  Width of the accounts-and-folders column in CSS pixels, [`MIN_SIDEBAR_WIDTH`] to
	 *  [`MAX_SIDEBAR_WIDTH`] ([`DEFAULT_SIDEBAR_WIDTH`] by default); the column's drag handle
	 *  sets it.
	 */
	sidebarWidth: number,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

type EventEmitTo<T> = [T] extends [null] ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void> : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>;

function makeEvent<TListen, TEmit = TListen>(name: string, serialize?: (payload: TEmit) => unknown, deserialize?: (payload: any) => TListen) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<TListen>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: TEmit) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => __TAURI_EVENT.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => target.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    });

    return Object.assign(fn, base);
}
